function esc(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function renderKvTable(rows, compact = false) {
  const cls = compact ? "fields fields--compact fields--grid" : "fields";
  return `<div class="${cls}">${rows
    .filter(([, v]) => v != null && v !== "")
    .map(([k, v, full]) => {
      const wide = full ? " field--full" : "";
      return `<button type="button" class="field${wide}" data-copy="${esc(String(v))}"><span class="field-k">${esc(k)}</span><span class="field-v">${esc(v)}</span>${compact ? "" : `<span class="field-hint">apasă copiază</span>`}</button>`;
    })
    .join("")}</div>`;
}

function normStr(s) {
  return String(s || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function buildClientBundle(sorted) {
  return sorted.map((c, i) => {
    const p = c.cerere_publica;
    const ci = c.check_in;
    const searchBlob = [p.guest_last_name, p.guest_first_name, p.guest_email, p.guest_phone]
      .filter(Boolean)
      .join(" ");
    let chk = null;
    if (ci) {
      chk = [
        ["Document", ci.doc_type],
        ["Serie", ci.doc_series],
        ["Nr.", ci.doc_number],
        ["Emis de", ci.doc_issued_by],
        ["Emitere", ci.doc_issue_date],
        ["Expirare", ci.doc_expiry_date],
        ["ID tip", ci.national_id_type],
        ["ID național", ci.national_id],
        ["Naștere", ci.birth_date],
        ["Loc naștere", ci.birth_place],
        ["Naționalitate", ci.nationality],
        ["Adresă", ci.address],
        ["Localitate", ci.city],
        ["Județ", ci.county],
        ["Țară", ci.country],
        ["Sex", ci.sex],
        ...(ci._expected_status ? [["Status", ci._expected_status]] : []),
      ].filter(([, v]) => v != null && v !== "");
    }
    return {
      id: c.id,
      page: i < 50 ? 1 : 2,
      pageIdx: (i % 50) + 1,
      fraud: c.test_tags?.length ? 1 : 0,
      nq: normStr(searchBlob),
      cet: c.cetatenie_cod,
      tip: c.tip_persoane,
      sup: c.suprapunere || "",
      tags: c.test_tags || [],
      doc: ci?.doc_type || "",
      pub: {
        checkIn: p.check_in,
        checkOut: p.check_out,
        adults: p.num_adults,
        children: p.num_children,
        minor: p.has_minor ? p.minor_age : null,
        last: p.guest_last_name,
        first: p.guest_first_name,
        email: p.guest_email,
        phone: p.guest_phone,
        notes: p.notes || "",
      },
      chk,
      neg: c.test_negativ || null,
    };
  });
}

