function firstValue(value: string | string[] | undefined): string {
  if (Array.isArray(value)) return value[0] ?? "";
  return value ?? "";
}

function normalizePage(value: string): number {
  const page = Number(value);
  return Number.isFinite(page) && page > 0 ? Math.floor(page) : 1;
}

function PaginationBar({
  pageLabel,
  searchLabel,
  previousLabel,
  nextLabel,
  result,
  currentHref,
}: {
  pageLabel: (page: number) => string;
  searchLabel: (query: string) => string;
  previousLabel: string;
  nextLabel: string;
  result: GuestSearchResult;
  currentHref: string;
}) {
  const current = parseGuestListHref(currentHref);
  return (
    <div className="guest-pagination">
      <p className="guest-pagination__info">
        {pageLabel(result.page)}
        {result.query ? ` · ${searchLabel(result.query)}` : ""}
      </p>
      <div className="guest-pagination__buttons">
        {result.hasPrevious ? (
          <Link
            href={buildGuestListHref({
              q: current.q,
              filter: current.filter,
              page: result.page - 1,
            })}
            className="guest-pagination__btn"
          >
            {previousLabel}
          </Link>
        ) : null}
        {result.hasMore ? (
          <Link
            href={buildGuestListHref({
              q: current.q,
              filter: current.filter,
              page: result.page + 1,
            })}
            className="guest-pagination__btn guest-pagination__btn--next"
          >
            {nextLabel}
          </Link>
        ) : null}
      </div>
    </div>
  );
}

export default async function AdminGuestsPage({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; filter?: string; page?: string; selected?: string }>;
}) {
  const t = await getTranslations("admin.pages.guests");
  const raw = await searchParams;
  const q = firstValue(raw.q);
  const filter = firstValue(raw.filter);
  const page = normalizePage(firstValue(raw.page));
  const selected = firstValue(raw.selected);
  const currentHref = buildGuestListHref({ q, filter, page });

  const FILTER_LINKS: { id: GuestSearchFilter; label: string }[] = [
    { id: "flagged", label: t("filterFlagged") },
    { id: "blacklist", label: t("filterBlacklist") },
    { id: "watchlist", label: t("filterWatchlist") },
    { id: "recent", label: t("filterRecent") },
    { id: "rated", label: t("filterRated") },
    { id: "loyal", label: t("filterLoyal") },
  ];

  let result: GuestSearchResult = {
    items: [],
    query: q,
    filter: (filter as GuestSearchFilter) || "all",
    page,
    pageSize: 20,
    hasMore: false,
    hasPrevious: false,
    mode: "highlights",
  };
  let highlights: Awaited<ReturnType<typeof listGuestHighlights>> | null = null;
  let selectedGuest: Awaited<ReturnType<typeof getGuestById>> = null;
  let error: string | null = null;

  try {
    result = await searchGuests({ query: q, filter, page, pageSize: 20 });
    if (result.mode === "highlights") {
      highlights = await listGuestHighlights();
    }
  } catch (e) {
    error = e instanceof Error ? e.message : t("genericError");
  }

  if (selected) {
    try {
      selectedGuest = await getGuestById(selected);
    } catch {
      selectedGuest = null;
    }
  }

  return (
    <main className="guest-page ml-content">
      <header className="guest-page__header guest-surface">
        <h1 className="guest-page__title">{t("title")}</h1>
        <p className="guest-page__desc">{t("description")}</p>
      </header>

      {error && <p className="guest-page__error">{error}</p>}

      <div className="guest-page__search-area guest-surface">
        <GuestSearchForm
          defaultQuery={q}
          defaultFilter={(result.filter as GuestSearchFilter) || "all"}
        />
        <div className="guest-filter-pills">
          {FILTER_LINKS.map((item) => (
            <Link
              key={item.id}
              href={buildGuestListHref({ filter: item.id })}
              className={[
                "guest-filter-pill",
                result.filter === item.id && "guest-filter-pill--active",
              ]
                .filter(Boolean)
                .join(" ")}
            >
              {item.label}
            </Link>
          ))}
        </div>
        <p className="guest-page__hint">{t("searchHint")}</p>
      </div>

      {result.mode === "highlights" && highlights ? (
        <div className="guest-highlights">
          <GuestRecentHeroSection
            eyebrow={t("filterRecent")}
            title={t("recentTitle")}
            description={t("recentDescription")}
            guests={highlights.recent}
            currentHref={currentHref}
            guestsCountLabel={t("guestsCount", { count: highlights.recent.length })}
            emptyLabel={t("sectionEmpty")}
          />
          <div className="guest-highlights__secondary">
            <GuestCollapsibleSection
              title={t("blacklistTitle")}
              description={t("blacklistDescription")}
              guests={highlights.blacklist}
              currentHref={currentHref}
              emptyLabel={t("sectionEmpty")}
            />
            <GuestCollapsibleSection
              title={t("loyalTitle")}
              description={t("loyalDescription")}
              guests={highlights.loyal}
              currentHref={currentHref}
              emptyLabel={t("sectionEmpty")}
            />
            <GuestCollapsibleSection
              title={t("ratedTitle")}
              description={t("ratedDescription")}
              guests={highlights.rated}
              currentHref={currentHref}
              emptyLabel={t("sectionEmpty")}
            />
          </div>
        </div>
      ) : (
        <section className="guest-results guest-surface">
          <h2 className="guest-results__title">{t("resultsTitle", { count: result.items.length })}</h2>
          {result.items.length === 0 ? (
            <AdminEmptyState
              emoji="🔎"
              title={t("emptyTitle")}
              description={t("emptyDescription")}
            />
          ) : (
            <>
              <ul className="guest-grid">
                {result.items.map((guest) => (
                  <GuestListCard
                    key={guest.id}
                    guest={guest}
                    previewHref={guestListPreviewHref(currentHref, guest.id)}
                    profileHref={guestProfileHref(currentHref, guest.id)}
                  />
                ))}
              </ul>
              <PaginationBar
                pageLabel={(p) => t("pageLabel", { page: p })}
                searchLabel={(query) => t("searchLabel", { query })}
                previousLabel={t("previous")}
                nextLabel={t("next")}
                result={result}
                currentHref={currentHref}
              />
            </>
          )}
        </section>
      )}

      <GuestPreviewPanel
        guest={selectedGuest}
        closeHref={currentHref}
        profileHref={
          selectedGuest
            ? `/admin/guests/${selectedGuest.id}?from=${encodeURIComponent(currentHref)}`
            : "/admin/guests"
        }
      />
    </main>
  );
}

﻿import { Link } from "@/i18n/navigation";
import { getTranslations } from "next-intl/server";
import "@/app/admin/admin-features.css";
import { AdminShellClient } from "@/components/admin/AdminShellClient";

import { AdminAppearanceProvider } from "@/components/admin/AdminAppearanceProvider";
import { AdminTopBar } from "@/components/admin/AdminTopBar";
import { SimOverlay } from "@/components/admin/SimOverlay";
import { countCereriNoi } from "@/services/bookings";
import type { ThemeSettings } from "@/lib/themes";
import {
  getPensionSettings,
  pensionAppearanceSettings,
} from "@/services/pension-settings";
import { resolveStaffRole } from "@/lib/auth/tenant-staff";
import { getStaffUser } from "@/lib/auth/require-staff";
import { isLocationConfigurationAccessible } from "@/lib/auth/location-unlock";
import { getSimStatus } from "@/domain/simulation/sim-cookie";
import { todayReal } from "@/domain/simulation/sim-clock";
import { isSimBackupPresent } from "@/services/simulation";
import { loadTodayBoard } from "@/services/today-board";
import { bindTenantContextFromRequest } from "@/lib/tenant/bind-request-context";
import { OnboardingBar } from "@/components/admin/onboarding/OnboardingBar";
import { AdminMobileBottomNav } from "@/layout/components/AdminMobileBottomNav";
import { MobileShell } from "@/layout/components/MobileShell";

const DEFAULT_APPEARANCE: ThemeSettings = {
  theme: "default",
  mode: "night",
};

export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const [, t, simBundle, batch, todayBoard] = await Promise.all([
    bindTenantContextFromRequest(),
    getTranslations("admin.layout"),
    (async () => {
      const simStatus = await getSimStatus();
      const simDbBackup = simStatus.active
        ? await isSimBackupPresent().catch(() => false)
        : true;
      return { simStatus, simDbBackup };
    })(),
    Promise.all([
      countCereriNoi().catch(() => 0),
      getPensionSettings().catch(() => null),
      (async () => {
        try {
          const user = await getStaffUser();
          const role = user ? await resolveStaffRole(user) : null;
          const locationUnlocked = user
            ? await isLocationConfigurationAccessible(user.id)
            : false;
          return {
            isAdmin: role === "admin",
            locationUnlocked,
          };
        } catch {
          return { isAdmin: false, locationUnlocked: false };
        }
      })(),
    ]),
    getPensionSettings()
      .catch(() => null)
      .then((pension) => {
        const checkInTime = pension?.default_check_in_time ?? "14:00";
        const checkOutTime = pension?.default_check_out_time ?? "11:00";
        return loadTodayBoard(checkInTime, checkOutTime).catch(() => null);
      }),
  ]);

  const { simStatus, simDbBackup } = simBundle;
  const [cereriCount, pension, staffAccess] = batch;
  const checkInTime = pension?.default_check_in_time ?? "14:00";
  const checkOutTime = pension?.default_check_out_time ?? "11:00";
  const { isAdmin, locationUnlocked } = staffAccess;

  let appearanceSettings: ThemeSettings = DEFAULT_APPEARANCE;
  if (pension) {
    appearanceSettings = pensionAppearanceSettings(pension);
  }

  return (
    <AdminAppearanceProvider initialSettings={appearanceSettings}>
      <MobileShell surface="admin" className="admin-shell flex min-h-full flex-1 flex-col">
        <div className="admin-hud">
          <div className="admin-hud__surface">
            <AdminTopBar
              board={todayBoard}
              cereriCount={cereriCount}
              locationUnlocked={locationUnlocked}
              isAdmin={isAdmin}
              simActive={simStatus.active}
              simDate={simStatus.active ? simStatus.currentDate : null}
              simDays={simStatus.active ? simStatus.daysAdvanced : 0}
            />
          </div>
        </div>

        <OnboardingBar />

        {cereriCount > 0 && (
          <div className="admin-hud-alert px-6 py-1.5 text-center text-xs">
            <Link href="/admin/bookings" className="admin-hud-alert__link">
              {t("pendingCount", { count: cereriCount })}
            </Link>{" "}
            {t("pendingSuffix")}
          </div>
        )}

        <AdminShellClient>
          <div className="admin-page-main ml-main flex-1">{children}</div>
        </AdminShellClient>

        <AdminMobileBottomNav
          cereriCount={cereriCount}
          locationUnlocked={locationUnlocked}
        />

        <SimOverlay
          active={simStatus.active}
          currentDate={simStatus.active ? simStatus.currentDate : null}
          daysAdvanced={simStatus.active ? simStatus.daysAdvanced : 0}
          realDate={todayReal()}
          dbBackupActive={simDbBackup}
        />
      </MobileShell>
    </AdminAppearanceProvider>
  );
}

"use server";

import { revalidatePath, revalidateTag } from "next/cache";
import { getTranslations } from "next-intl/server";
import { localeRedirect as redirect } from "@/i18n/server-redirect";
import { requireLocationAdmin } from "@/lib/auth/require-staff";
import { CACHE_TAGS } from "@/lib/cache-tags";
import { listBuildings } from "@/services/buildings";
import { parseSelectedOptionIds } from "@/services/room-catalog";
import { updateRoom } from "@/services/rooms-admin";
import { logAdminActivityFromSession } from "@/services/activity-log";
import { revalidateStructurePaths } from "@/lib/cache/revalidate-structure";

function roomReturnPath(formData: FormData): string {
  const raw = String(formData.get("return_to") ?? "").trim();
  if (raw === "structure") return "/admin/settings/location/structure";
  return "";
}

export async function updateRoomAction(formData: FormData) {
  await requireLocationAdmin();
  const t = await getTranslations("admin.serverActions");

  const id = String(formData.get("id") ?? "");
  const building_id = String(formData.get("building_id") ?? "");
  const floor_id = String(formData.get("floor_id") ?? "");
  const name = String(formData.get("name") ?? "");
  const room_type_definition_id = String(
    formData.get("room_type_definition_id") ?? ""
  );
  const capacity_base = Number(formData.get("capacity_base") ?? 2);
  const price_per_night = Number(formData.get("price_per_night") ?? 0);
  const sort_order = Number(formData.get("sort_order") ?? 0);
  const allows_extra_beds = formData.get("allows_extra_beds") === "on";
  const max_extra_beds_per_room = Number(
    formData.get("max_extra_beds_per_room") ?? 0
  );
  const is_active = formData.get("is_active") === "on";
  const enabled_option_ids = parseSelectedOptionIds(formData).filter(Boolean);

  if (!id || !building_id || !name) {
    throw new Error(t("roomUpdateIncomplete"));
  }

  const buildings = await listBuildings();
  const b = buildings.find((x) => x.id === building_id);

  await updateRoom(id, {
    building_id,
    floor_id: floor_id || null,
    name,
    room_type_definition_id: room_type_definition_id || null,
    capacity_base,
    allows_extra_beds,
    max_extra_beds_per_room,
    enabled_option_ids,
    price_per_night,
    sort_order,
    is_active,
    building_default_price: b?.default_price_per_night ?? 0,
  });

  await logAdminActivityFromSession({
    action: "room.updated",
    entityType: "room",
    entityId: id,
    summary: t("roomUpdatedSummary", { name }),
    metadata: { is_active, room_type_definition_id },
  });

  revalidateStructurePaths();
  revalidateTag(CACHE_TAGS.roomOptionsByRoom, "max");
  const back = roomReturnPath(formData);
  await redirect(back || "/admin/rooms");
}

"use server";

import { headers } from "next/headers";
import { revalidatePath, revalidateTag } from "next/cache";
import { isRedirectError } from "next/dist/client/components/redirect-error";
import { localeRedirect as redirect } from "@/i18n/server-redirect";
import { requireLocationAdmin } from "@/lib/auth/require-staff";
import { CACHE_TAGS } from "@/lib/cache-tags";
import { listBuildings } from "@/services/buildings";
import { parseSelectedOptionIds } from "@/services/room-catalog";
import { createRoom, createRoomsBulk } from "@/services/rooms-admin";
import { logAdminActivityFromSession } from "@/services/activity-log";
import { captureTenantError } from "@/services/dev-logs";
import { revalidateStructurePaths } from "@/lib/cache/revalidate-structure";
import { getTranslations } from "next-intl/server";

function roomReturnPath(formData: FormData): string {
  const raw = String(formData.get("return_to") ?? "").trim();
  if (raw === "structure") return "/admin/settings/location/structure";
  return "";
}

function roomFormQueryParams(formData: FormData, params: URLSearchParams): URLSearchParams {
  const building = String(formData.get("building_id") ?? "").trim();
  const floor = String(formData.get("floor_id") ?? "").trim();
  const returnTo = String(formData.get("return_to") ?? "").trim();
  if (building) params.set("building", building);
  if (floor) params.set("floor", floor);
  if (returnTo) params.set("return_to", returnTo);
  return params;
}

/** La succes — poate reveni la structură; la erori rămâne pe formular. */
function roomSuccessRedirectPath(formData: FormData): string {
  return roomReturnPath(formData) || "/admin/rooms";
}

function roomFormErrorRedirectPath(formData: FormData, params: URLSearchParams): string {
  const q = roomFormQueryParams(formData, params).toString();
  return q ? `/admin/rooms/new?${q}` : "/admin/rooms/new";
}

async function requestHostForLog(): Promise<string | null> {
  const h = await headers();
  return h.get("x-forwarded-host") ?? h.get("host");
}

async function logCreateRoomFailure(
  error: unknown,
  context: Record<string, unknown>
): Promise<void> {
  const err = error instanceof Error ? error : new Error(String(error));
  await captureTenantError(err, {
    source: "action",
    requestPath: "/admin/rooms/new",
    requestMethod: "POST",
    requestHost: await requestHostForLog(),
    context: {
      action: "createRoomAction",
      ...context,
    },
  });
}

async function redirectRoomFormError(
  formData: FormData,
  code: string,
  extra?: URLSearchParams,
  logContext?: Record<string, unknown>
) {
  if (logContext) {
    await logCreateRoomFailure(new Error(`rooms.${code}`), {
      errorCode: code,
      building_id: String(formData.get("building_id") ?? ""),
      floor_id: String(formData.get("floor_id") ?? ""),
      create_mode: String(formData.get("create_mode") ?? ""),
      ...logContext,
    });
  }
  const params = new URLSearchParams({ error: code });
  if (extra) {
    for (const [key, value] of extra.entries()) {
      params.set(key, value);
    }
  }
  await redirect(roomFormErrorRedirectPath(formData, params));
}

export async function createRoomAction(formData: FormData) {
  const t = await getTranslations("admin.serverActions");

  try {
    await requireLocationAdmin();

    const create_mode = String(formData.get("create_mode") ?? "single");
    const building_id = String(formData.get("building_id") ?? "");
    const floor_id = String(formData.get("floor_id") ?? "");
    const room_type_definition_id = String(
      formData.get("room_type_definition_id") ?? ""
    );
    const price_per_night = Number(formData.get("price_per_night") ?? 0);
    const sort_order = Number(formData.get("sort_order") ?? 0);
    const allows_extra_beds = formData.get("allows_extra_beds") === "on";
    const max_extra_beds_per_room = Number(
      formData.get("max_extra_beds_per_room") ?? 0
    );
    const enabled_option_ids = parseSelectedOptionIds(formData).filter(Boolean);

    if (!building_id || !room_type_definition_id) {
      await redirectRoomFormError(formData, "server", undefined, {
        reason: "missing_building_or_type",
      });
      return;
    }

    const buildings = await listBuildings();
    const b = buildings.find((x) => x.id === building_id);
    const building_default_price = b?.default_price_per_night ?? 0;

    if (create_mode === "bulk") {
      const naming_mode =
        String(formData.get("bulk_naming_mode") ?? "prefix") === "number_only"
          ? "number_only"
          : "prefix";
      const name_prefix =
        naming_mode === "number_only"
          ? ""
          : String(formData.get("name_prefix") ?? "").trim();
      const start_number = Number(formData.get("start_number") ?? 1);
      const bulk_count = Number(formData.get("bulk_count") ?? 1);

      let ids: string[];
      try {
        ({ ids } = await createRoomsBulk({
          building_id,
          floor_id: floor_id || null,
          room_type_definition_id,
          count: bulk_count,
          name_prefix,
          start_number,
          naming_mode,
          allows_extra_beds,
          max_extra_beds_per_room,
          enabled_option_ids,
          price_per_night,
          sort_order_start: sort_order,
          building_default_price,
        }));
      } catch (e) {
        if (e instanceof Error && e.message.startsWith("rooms.bulk_duplicate_names:")) {
          const list = e.message.replace("rooms.bulk_duplicate_names:", "");
          await redirectRoomFormError(
            formData,
            "bulk_duplicate",
            new URLSearchParams({ names: list }),
            { reason: "bulk_duplicate_names", names: list }
          );
        }
        if (
          e instanceof Error &&
          e.message === "rooms.bulk_count_must_be_between_1_and_50"
        ) {
          await redirectRoomFormError(formData, "bulk_count", undefined, {
            reason: "bulk_count_invalid",
          });
        }
        if (e instanceof Error && e.message === "floors.building_mismatch") {
          await redirectRoomFormError(formData, "floor_mismatch", undefined, {
            reason: "floor_building_mismatch",
          });
        }
        if (
          e instanceof Error &&
          e.message.includes("rooms_room_type_check")
        ) {
          await redirectRoomFormError(formData, "room_type_constraint", undefined, {
            reason: "rooms_room_type_check",
            message: e.message,
          });
        }
        await logCreateRoomFailure(e, {
          reason: "bulk_create_unhandled",
          building_id,
          floor_id,
        });
        throw e;
      }

      await logAdminActivityFromSession({
        action: "room.created",
        entityType: "room",
        summary: t("bulkRoomsSummary", {
          count: ids.length,
          prefix: name_prefix,
          start: start_number,
        }),
        metadata: { building_id, bulk_count, room_type_definition_id },
      });

      revalidateStructurePaths();
      revalidateTag(CACHE_TAGS.roomOptionsByRoom, "max");
      const back = roomSuccessRedirectPath(formData);
      await redirect(back === "/admin/rooms" ? `${back}?bulk=${ids.length}` : back);
    }

    const name = String(formData.get("name") ?? "");
    if (!name) {
      await redirectRoomFormError(formData, "server", undefined, {
        reason: "missing_room_name",
      });
      return;
    }

    let room: { id: string };
    try {
      room = await createRoom({
        building_id,
        floor_id: floor_id || null,
        name,
        room_type_definition_id,
        capacity_base: 2,
        allows_extra_beds,
        max_extra_beds_per_room,
        enabled_option_ids,
        price_per_night,
        sort_order,
        building_default_price,
      });
    } catch (e) {
      if (e instanceof Error && e.message.startsWith("rooms.duplicate_name:")) {
        const dup = e.message.replace("rooms.duplicate_name:", "");
        await redirectRoomFormError(
          formData,
          "duplicate_name",
          new URLSearchParams({ names: dup }),
          { reason: "duplicate_name", names: dup }
        );
      }
      if (e instanceof Error && e.message === "floors.building_mismatch") {
        await redirectRoomFormError(formData, "floor_mismatch", undefined, {
          reason: "floor_building_mismatch",
        });
      }
      if (
        e instanceof Error &&
        e.message.includes("rooms_room_type_check")
      ) {
        await redirectRoomFormError(formData, "room_type_constraint", undefined, {
          reason: "rooms_room_type_check",
          message: e.message,
        });
      }
      await logCreateRoomFailure(e, {
        reason: "single_create_unhandled",
        building_id,
        floor_id,
        name,
      });
      throw e;
    }

    await logAdminActivityFromSession({
      action: "room.created",
      entityType: "room",
      entityId: room.id,
      summary: t("newRoomSummary", { name }),
      metadata: { building_id, room_type_definition_id },
    });

    revalidateStructurePaths();
    revalidateTag(CACHE_TAGS.roomOptionsByRoom, "max");
    await redirect(roomSuccessRedirectPath(formData));
  } catch (e) {
    if (isRedirectError(e)) throw e;
    await logCreateRoomFailure(e, { reason: "outer_catch" });
    await redirectRoomFormError(formData, "server");
  }
}

