"use client";

import type { Building, Floor } from "@/types/database";
import type { RoomOptionDefinition, RoomTypeDefinition } from "@/types/room-catalog";
import type { OptionPolicyMode } from "@/types/room-catalog";
import {
  buildBulkRoomNames,
  findDuplicateRoomNames,
  suggestNextBulkStartNumber,
  type BulkNamingMode,
} from "@/domain/room/bulk-names";
import { roomScopeKey } from "@/domain/room/scope-key";
import { computeRoomPrice, policyModeForOption, resolveOptionEnabled } from "@/lib/room-catalog-pricing";
import { useEffect, useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import { AdminPendingForm } from "@/components/admin/feedback/AdminPendingForm";
import { AdminSubmitButton } from "@/components/admin/feedback/AdminSubmitButton";
import { RoomOptionFields } from "@/components/admin/catalog/RoomOptionFields";

type Props = {
  buildings: Building[];
  floorsByBuilding: Record<string, Floor[]>;
  types: RoomTypeDefinition[];
  options: RoomOptionDefinition[];
  policiesByBuilding: Record<string, { option_id: string; mode: OptionPolicyMode }[]>;
  createRoomAction: (formData: FormData) => Promise<void>;
  existingNamesByScope?: Record<string, string[]>;
  nextSortByBuilding?: Record<string, number>;
  defaultBuildingId?: string;
  defaultFloorId?: string;
  returnTo?: "structure";
  formError?: string | null;
};

function suggestPrice(
  building: Building | undefined,
  selectedType: RoomTypeDefinition | null,
  options: RoomOptionDefinition[],
  policies: { option_id: string; mode: OptionPolicyMode }[]
): number {
  if (!building) return 0;
  const defaultOptionIds = selectedType?.default_option_ids ?? [];
  const enabledOptions = options.filter((opt) => {
    const mode = policyModeForOption(policies, opt.id);
    return resolveOptionEnabled(
      mode,
      defaultOptionIds.includes(opt.id),
      defaultOptionIds.includes(opt.id)
    ).enabled;
  });
  return computeRoomPrice({
    type: selectedType,
    buildingDefaultPrice: building.default_price_per_night ?? 0,
    enabledOptions,
  });
}

export function RoomForm({
  buildings,
  floorsByBuilding,
  types,
  options,
  policiesByBuilding,
  createRoomAction,
  existingNamesByScope = {},
  nextSortByBuilding = {},
  defaultBuildingId,
  defaultFloorId,
  returnTo,
  formError,
}: Props) {
  const tCommon = useTranslations("admin.common");
  const tRooms = useTranslations("admin.roomForm");
  const [mode, setMode] = useState<"single" | "bulk">("single");
  const initial =
    defaultBuildingId && buildings.some((b) => b.id === defaultBuildingId)
      ? defaultBuildingId
      : (buildings[0]?.id ?? "");
  const [buildingId, setBuildingId] = useState(initial);
  const initialFloor =
    defaultFloorId &&
    (floorsByBuilding[initial] ?? []).some((f) => f.id === defaultFloorId)
      ? defaultFloorId
      : "";
  const [floorId, setFloorId] = useState(initialFloor);
  const defaultTypeId = types.find((t) => t.slug === "double")?.id ?? types[0]?.id ?? "";
  const [typeId, setTypeId] = useState(defaultTypeId);
  const [bulkNaming, setBulkNaming] = useState<BulkNamingMode>("number_only");
  const [namePrefix, setNamePrefix] = useState("");
  const [startNumber, setStartNumber] = useState(1);
  const [endNumber, setEndNumber] = useState(10);
  const [sortOrder, setSortOrder] = useState(1);

  const building = buildings.find((b) => b.id === buildingId);
  const floors = floorsByBuilding[buildingId] ?? [];
  const policies = policiesByBuilding[buildingId] ?? [];
  const selectedType = types.find((t) => t.id === typeId) ?? null;

  const suggestedPrice = useMemo(
    () => suggestPrice(building, selectedType, options, policies),
    [building, selectedType, options, policies]
  );

  const existingNames = useMemo(
    () => existingNamesByScope[roomScopeKey(buildingId, floorId || null)] ?? [],
    [existingNamesByScope, buildingId, floorId]
  );

  useEffect(() => {
    const nextSort = nextSortByBuilding[buildingId] ?? 1;
    setSortOrder(nextSort);
    if (mode !== "bulk") return;
    const nextStart = suggestNextBulkStartNumber(
      existingNames,
      bulkNaming,
      bulkNaming === "number_only" ? "" : namePrefix
    );
    setStartNumber(nextStart);
    setEndNumber(nextStart + 9);
  }, [buildingId, floorId, mode, bulkNaming, namePrefix, existingNames, nextSortByBuilding]);

  const bulkCount = Math.max(1, (endNumber || startNumber) - startNumber + 1);

  const bulkPreview = useMemo(() => {
    if (mode !== "bulk") return [];
    const count = Math.min(50, Math.max(1, bulkCount));
    return buildBulkRoomNames(
      bulkNaming,
      bulkNaming === "number_only" ? "" : namePrefix,
      startNumber || 1,
      count
    );
  }, [mode, bulkNaming, namePrefix, startNumber, bulkCount]);

  const bulkConflicts = useMemo(() => {
    if (mode !== "bulk" || bulkPreview.length === 0) return [];
    return findDuplicateRoomNames(existingNames, bulkPreview);
  }, [mode, bulkPreview, existingNames]);

  const bulkBlocked = mode === "bulk" && bulkConflicts.length > 0;

  return (
    <div className="mt-6 space-y-4">
      {formError ? (
        <p className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800">
          {formError}
        </p>
      ) : null}
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => setMode("single")}
          className={`rounded-lg px-3 py-1.5 text-sm ${mode === "single" ? "bg-zinc-900 text-white" : "border border-zinc-300"}`}
        >
          {tRooms("singleRoom")}
        </button>
        <button
          type="button"
          onClick={() => setMode("bulk")}
          className={`rounded-lg px-3 py-1.5 text-sm ${mode === "bulk" ? "bg-zinc-900 text-white" : "border border-zinc-300"}`}
        >
          {tRooms("bulkMany")}
        </button>
      </div>

      <AdminPendingForm action={createRoomAction} className="space-y-5">
        <input type="hidden" name="create_mode" value={mode} />
        {returnTo && <input type="hidden" name="return_to" value={returnTo} />}

        <label className="block">
          <span className="text-sm font-medium">{tCommon("building")} *</span>
          <select
            name="building_id"
            required
            value={buildingId}
            onChange={(e) => {
              setBuildingId(e.target.value);
              setFloorId("");
            }}
            className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
          >
            {buildings.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name}
              </option>
            ))}
          </select>
        </label>

        <label className="block">
          <span className="text-sm font-medium">{tRooms("floorOptional")}</span>
          <select
            name="floor_id"
            className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
            value={floorId}
            onChange={(e) => setFloorId(e.target.value)}
          >
            <option value="">{tRooms("withoutFloor")}</option>
            {floors.map((f) => (
              <option key={f.id} value={f.id}>
                {f.name}
              </option>
            ))}
          </select>
        </label>

        <label className="block">
          <span className="text-sm font-medium">{tRooms("roomTypeRequired")}</span>
          <select
            name="room_type_definition_id"
            required
            value={typeId}
            onChange={(e) => setTypeId(e.target.value)}
            className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
          >
            {types.map((t) => (
              <option key={t.id} value={t.id}>
                {t.name} · {t.capacity_base} {tCommon("personsShort")}
                {t.base_price_per_night > 0 ? ` · ${t.base_price_per_night} RON` : ""}
              </option>
            ))}
          </select>
        </label>

        {mode === "single" ? (
          <label className="block">
            <span className="text-sm font-medium">{tRooms("roomNameRequired")}</span>
            <input
              name="name"
              required
              placeholder={tRooms("roomNamePlaceholderPlain")}
              className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
            />
          </label>
        ) : (
          <div className="space-y-4">
            <fieldset className="space-y-2">
              <legend className="text-sm font-medium text-zinc-900">
                {tRooms("bulkNamingLegend")}
              </legend>
              <label className="flex items-center gap-2 text-sm">
                <input
                  type="radio"
                  name="bulk_naming_mode"
                  value="number_only"
                  checked={bulkNaming === "number_only"}
                  onChange={() => setBulkNaming("number_only")}
                />
                {tRooms("bulkNamingNumbersOnly")}
              </label>
              <label className="flex items-center gap-2 text-sm">
                <input
                  type="radio"
                  name="bulk_naming_mode"
                  value="prefix"
                  checked={bulkNaming === "prefix"}
                  onChange={() => setBulkNaming("prefix")}
                />
                {tRooms("bulkNamingPrefix")}
              </label>
            </fieldset>
            <div className="grid gap-4 sm:grid-cols-3">
              {bulkNaming === "prefix" ? (
                <label className="block sm:col-span-1">
                  <span className="text-sm font-medium">{tRooms("namePrefixOptional")}</span>
                  <span className="mt-0.5 block text-xs text-zinc-500">
                    {tRooms("namePrefixEmptyHint")}
                  </span>
                  <input
                    name="name_prefix"
                    value={namePrefix}
                    onChange={(e) => setNamePrefix(e.target.value)}
                    placeholder={tRooms("namePrefixPlaceholder")}
                    className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
                  />
                </label>
              ) : (
                <input type="hidden" name="name_prefix" value="" />
              )}
              <label className="block">
                <span className="text-sm font-medium">{tRooms("startNumber")}</span>
                <input
                  name="start_number"
                  type="number"
                  min={1}
                  value={startNumber}
                  onChange={(e) => {
                    const v = Number(e.target.value) || 1;
                    setStartNumber(v);
                    if (endNumber < v) setEndNumber(v);
                  }}
                  className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
                />
              </label>
              <label className="block">
                <span className="text-sm font-medium">{tRooms("endNumber")}</span>
                <input
                  name="end_number"
                  type="number"
                  min={startNumber}
                  max={startNumber + 49}
                  value={endNumber}
                  onChange={(e) => setEndNumber(Number(e.target.value) || startNumber)}
                  className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
                />
              </label>
              <input type="hidden" name="bulk_count" value={bulkCount} />
            </div>
            {bulkPreview.length > 0 && (
              <div
                className={[
                  "rounded-lg border px-3 py-2 text-xs",
                  bulkConflicts.length > 0
                    ? "border-red-200 bg-red-50 text-red-800"
                    : "border-zinc-200 bg-zinc-50 text-zinc-700",
                ].join(" ")}
              >
                <span className="font-semibold">{tRooms("bulkPreviewLabel")}: </span>
                {bulkPreview.join(", ")}
                {bulkPreview.length >= 50 ? " …" : ""}
                {bulkConflicts.length > 0 ? (
                  <p className="mt-1.5 font-semibold">
                    {tRooms("bulkConflictWarning", {
                      names: bulkConflicts.join(", "),
                    })}
                  </p>
                ) : (
                  <p className="mt-1.5 text-zinc-500">{tRooms("bulkAutoStartHint")}</p>
                )}
              </div>
            )}
          </div>
        )}

        <RoomOptionFields
          options={options}
          policies={policies}
          selectedType={selectedType}
          selectedOptionIds={selectedType?.default_option_ids ?? []}
        />

        <div className="grid grid-cols-2 gap-4">
          <label className="block">
            <span className="text-sm font-medium">{tRooms("pricePerNightRon")}</span>
            <span className="block text-xs text-zinc-500">
              {tRooms("autoPriceHint", { suggestedPrice })}
            </span>
            <input
              name="price_per_night"
              type="number"
              min={0}
              step={1}
              key={`${buildingId}-${typeId}`}
              defaultValue={suggestedPrice || building?.default_price_per_night || 0}
              className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
            />
          </label>
          <label className="block">
            <span className="text-sm font-medium">{tCommon("displayOrder")}</span>
            <input
              name="sort_order"
              type="number"
              value={sortOrder}
              onChange={(e) => setSortOrder(Number(e.target.value) || 1)}
              className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
            />
          </label>
        </div>

        <label className="flex items-center gap-2">
          <input type="checkbox" name="allows_extra_beds" className="rounded" />
          <span className="text-sm">{tRooms("allowExtraBeds")}</span>
        </label>

        <label className="block">
          <span className="text-sm font-medium">{tRooms("maxExtraBeds")}</span>
          <input
            name="max_extra_beds_per_room"
            type="number"
            min={0}
            max={4}
            defaultValue={1}
            className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2"
          />
        </label>

        <AdminSubmitButton
          disabled={bulkBlocked}
          className="rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
        >
          {mode === "bulk" ? tRooms("createRooms") : tRooms("saveRoom")}
        </AdminSubmitButton>
      </AdminPendingForm>
    </div>
  );
}

import { Suspense } from "react";
import { Link } from "@/i18n/navigation";
import { AvailabilityDashboard } from "@/components/admin/availability/AvailabilityDashboard";
import { loadAvailabilityDashboard } from "@/services/availability-month";
import { parseGanttFeatureFilter } from "@/lib/gantt-query";
import { mondayOfWeekIso } from "@/domain/availability/week-range";
import { todayIso } from "@/lib/stay-dates";
import { getTranslations } from "next-intl/server";
import { getEffectiveToday } from "@/domain/simulation/sim-clock";

export type AvailabilityShellSearchParams = {
  y?: string;
  m?: string;
  day?: string;
  building?: string;
  view?: string;
  ws?: string;
  feat?: string;
};

function buildBaseQuery(
  year: number,
  month: number,
  extra: Record<string, string | undefined>
) {
  const p = new URLSearchParams({ y: String(year), m: String(month) });
  for (const [key, value] of Object.entries(extra)) {
    if (value) p.set(key, value);
  }
  return p.toString();
}

function buildHref(basePath: string, query: string, anchorHash?: string) {
  return `${basePath}?${query}${anchorHash ?? ""}`;
}

export async function AvailabilityDashboardShell({
  searchParams,
  basePath,
  anchorHash,
  className = "",
}: {
  searchParams: AvailabilityShellSearchParams;
  basePath: string;
  anchorHash?: string;
  className?: string;
}) {
  const tCommon = await getTranslations("admin.common");
  const tPage = await getTranslations("admin.availability");
  const effectiveToday = await getEffectiveToday();
  const refDate = new Date(effectiveToday + "T00:00:00");
  const year = Number(searchParams.y) || refDate.getFullYear();
  const month = searchParams.m !== undefined ? Number(searchParams.m) : refDate.getMonth();
  const buildingId = searchParams.building?.length ? searchParams.building : null;
  const featureFilter = parseGanttFeatureFilter(searchParams.feat);
  const view = searchParams.view === "week" ? "week" : "month";
  const weekStart =
    searchParams.ws ?? (view === "week" ? mondayOfWeekIso(searchParams.day ?? effectiveToday) : null);

  const prevM = month === 0 ? 11 : month - 1;
  const prevY = month === 0 ? year - 1 : year;
  const nextM = month === 11 ? 0 : month + 1;
  const nextY = month === 11 ? year + 1 : year;

  let dashboard: Awaited<ReturnType<typeof loadAvailabilityDashboard>> | null = null;
  let error: string | null = null;

  try {
    dashboard = await loadAvailabilityDashboard(year, month, buildingId, featureFilter);
  } catch (e) {
    error = e instanceof Error ? e.message : tCommon("error");
  }

  if (error) {
    return (
      <p className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800">
        {error}
      </p>
    );
  }

  if (!dashboard) return null;

  const sharedExtra = {
    building: buildingId ?? undefined,
    feat: featureFilter !== "all" ? featureFilter : undefined,
    view: view === "week" ? "week" : undefined,
    ws: view === "week" ? weekStart ?? undefined : undefined,
  };

  return (
    <div className={className}>
      <div className="mb-4 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2">
          <Link
            href={buildHref(
              basePath,
              buildBaseQuery(prevY, prevM, sharedExtra),
              anchorHash
            )}
            className="border border-zinc-300 px-3 py-2 text-sm font-medium"
          >
            ←
          </Link>
          <span className="px-2 py-1.5 text-sm font-medium capitalize">{dashboard.title}</span>
          <Link
            href={buildHref(
              basePath,
              buildBaseQuery(nextY, nextM, sharedExtra),
              anchorHash
            )}
            className="border border-zinc-300 px-3 py-2 text-sm font-medium"
          >
            →
          </Link>
        </div>
        <p className="text-sm">
          <strong>{dashboard.total_rooms}</strong> {tCommon("rooms")}
          {buildingId && ` (${tPage("buildingFilterActive")})`}
        </p>
      </div>

      <Suspense
        fallback={
          <div className="border border-dashed border-zinc-200 p-12 text-center text-sm text-zinc-500">
            {tPage("loadingPanel")}
          </div>
        }
      >
        <AvailabilityDashboard
          dashboard={dashboard}
          initialDay={searchParams.day}
          buildingId={buildingId}
          featureFilter={featureFilter}
          view={view}
          weekStart={weekStart}
          basePath={basePath}
          anchorHash={anchorHash}
          today={effectiveToday}
        />
      </Suspense>
    </div>
  );
}

"use client";

import { useCallback, useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { validateCheckin } from "@/domain/checkin/validate";
import { useAdminFx } from "@/components/admin/feedback/AdminToastProvider";
import { createCheckinAction } from "@/app/[locale]/admin/(panel)/checkin/actions";
import type {
  BookingForCheckin,
  CheckinFormData,
  CheckinGuestInput,
  CheckinSettings,
  PaymentStatus,
  ValidationResult,
} from "@/domain/checkin/types";

type Props = {
  booking: BookingForCheckin;
  settings: CheckinSettings;
  onComplete: () => void;
  onCancel: () => void;
};

const STEPS = ["identity", "validate", "payment", "finish"] as const;
type StepKey = (typeof STEPS)[number];

export function CheckinStepper({
  booking,
  settings,
  onComplete,
  onCancel,
}: Props) {
  const t = useTranslations("admin.checkIn");
  const { showToast } = useAdminFx();
  const [pending, startTransition] = useTransition();

  // Step state
  const [currentStep, setCurrentStep] = useState(0);

  // Guest data — pre-populated from booking
  const [guests, setGuests] = useState<CheckinGuestInput[]>([
    {
      full_name: booking.guest_name,
      phone: booking.guest_phone ?? "",
      document_type: null,
      document_number: "",
      nationality: "",
      birth_date: "",
      is_representative: true,
      guest_id: null,
    },
  ]);

  // Payment data
  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus>("unpaid");
  const [paymentAmount, setPaymentAmount] = useState(booking.total_price);
  const [depositAmount, setDepositAmount] = useState(
    settings.checkin_deposit ? settings.checkin_deposit_amount : 0,
  );

  // Finalize data
  const [keyHanded, setKeyHanded] = useState(false);
  const [notes, setNotes] = useState("");

  // Validation result (computed on step 1)
  const [validation, setValidation] = useState<ValidationResult | null>(null);

  // Error
  const [error, setError] = useState<string | null>(null);

  const buildFormData = useCallback((): CheckinFormData => {
    return {
      type: "reservation",
      booking_id: booking.id,
      guests,
      payment_status: paymentStatus,
      payment_amount_paid:
        paymentStatus === "paid"
          ? booking.total_price
          : paymentStatus === "partial"
            ? paymentAmount
            : 0,
      deposit_amount: settings.checkin_deposit ? depositAmount : 0,
      key_handed: keyHanded,
      notes: notes || undefined,
    };
  }, [
    booking,
    guests,
    paymentStatus,
    paymentAmount,
    depositAmount,
    keyHanded,
    notes,
    settings,
  ]);

  // ── Navigation ────────────────────────────────────────────

  function goNext() {
    if (currentStep === 0) {
      // Moving from identity → validate: run validation
      const data = buildFormData();
      const now = new Date();
      const currentHour = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
      const result = validateCheckin(data, settings, booking, currentHour);
      setValidation(result);
    }
    setCurrentStep((s) => Math.min(s + 1, STEPS.length - 1));
  }

  function goBack() {
    setCurrentStep((s) => Math.max(s - 1, 0));
  }

  // ── Submit ────────────────────────────────────────────────

  function handleSubmit() {
    setError(null);
    startTransition(async () => {
      const data = buildFormData();
      const fd = new FormData();
      fd.set("booking_id", data.booking_id);
      fd.set("type", data.type);
      fd.set("payment_status", data.payment_status);
      fd.set("payment_amount_paid", String(data.payment_amount_paid ?? 0));
      fd.set("deposit_amount", String(data.deposit_amount ?? 0));
      fd.set("key_handed", String(data.key_handed ?? false));
      fd.set("notes", data.notes ?? "");
      fd.set("guests", JSON.stringify(data.guests));

      const result = await createCheckinAction(fd);
      if (result.ok) {
        showToast({
          kind: "success",
          title: t("success"),
        });
        onComplete();
      } else {
        setError(result.error ?? "Unknown error");
      }
    });
  }

  // ── Guest field update helper ─────────────────────────────

  function updateGuest(
    index: number,
    field: keyof CheckinGuestInput,
    value: string | boolean | null,
  ) {
    setGuests((prev) =>
      prev.map((g, i) => (i === index ? { ...g, [field]: value } : g)),
    );
  }

  // ── Render ────────────────────────────────────────────────

  const stepKey = STEPS[currentStep];

  return (
    <div className="checkin-stepper">
      {/* Step indicators */}
      <div className="checkin-stepper__indicators">
        {STEPS.map((s, i) => (
          <div
            key={s}
            className={`checkin-stepper__indicator ${
              i === currentStep
                ? "checkin-stepper__indicator--active"
                : i < currentStep
                  ? "checkin-stepper__indicator--done"
                  : ""
            }`}
          >
            <span className="checkin-stepper__indicator-num">{i + 1}</span>
            <span className="checkin-stepper__indicator-label">
              {t(`step.${s}`)}
            </span>
          </div>
        ))}
      </div>

      {/* Step content */}
      <div className="checkin-stepper__content">
        {stepKey === "identity" && (
          <StepIdentity
            guests={guests}
            updateGuest={updateGuest}
            t={t}
          />
        )}

        {stepKey === "validate" && (
          <StepValidation validation={validation} t={t} />
        )}

        {stepKey === "payment" && (
          <StepPayment
            booking={booking}
            settings={settings}
            paymentStatus={paymentStatus}
            paymentAmount={paymentAmount}
            depositAmount={depositAmount}
            onPaymentStatusChange={setPaymentStatus}
            onPaymentAmountChange={setPaymentAmount}
            onDepositAmountChange={setDepositAmount}
            t={t}
          />
        )}

        {stepKey === "finish" && (
          <StepFinish
            booking={booking}
            guests={guests}
            paymentStatus={paymentStatus}
            validation={validation}
            keyHanded={keyHanded}
            notes={notes}
            onKeyHandedChange={setKeyHanded}
            onNotesChange={setNotes}
            t={t}
          />
        )}
      </div>

      {/* Error */}
      {error && (
        <div className="checkin-stepper__error">{error}</div>
      )}

      {/* Navigation buttons */}
      <div className="checkin-stepper__nav">
        {currentStep === 0 ? (
          <button
            type="button"
            className="checkin-stepper__btn checkin-stepper__btn--secondary"
            onClick={onCancel}
          >
            {t("cancel")}
          </button>
        ) : (
          <button
            type="button"
            className="checkin-stepper__btn checkin-stepper__btn--secondary"
            onClick={goBack}
            disabled={pending}
          >
            {t("back")}
          </button>
        )}

        {currentStep < STEPS.length - 1 ? (
          <button
            type="button"
            className="checkin-stepper__btn checkin-stepper__btn--primary"
            onClick={goNext}
            disabled={
              stepKey === "validate" &&
              validation?.status === "blocked"
            }
          >
            {t("next")}
          </button>
        ) : (
          <button
            type="button"
            className="checkin-stepper__btn checkin-stepper__btn--primary"
            onClick={handleSubmit}
            disabled={pending}
          >
            {pending ? t("saving") : t("confirm")}
          </button>
        )}
      </div>
    </div>
  );
}

// ── Step sub-components (co-located for simplicity) ─────────

function StepIdentity({
  guests,
  updateGuest,
  t,
}: {
  guests: CheckinGuestInput[];
  updateGuest: (i: number, f: keyof CheckinGuestInput, v: string | boolean | null) => void;
  t: ReturnType<typeof useTranslations>;
}) {
  return (
    <div className="checkin-step-identity">
      {guests.map((guest, idx) => (
        <div key={idx} className="checkin-guest-form">
          <div className="checkin-guest-form__header">
            {t("guestN", { n: idx + 1 })}
          </div>

          <div className="checkin-guest-form__grid">
            <label className="checkin-field">
              <span className="checkin-field__label">{t("field.fullName")}</span>
              <input
                type="text"
                className="checkin-field__input"
                value={guest.full_name}
                onChange={(e) => updateGuest(idx, "full_name", e.target.value)}
                required
              />
            </label>

            <label className="checkin-field">
              <span className="checkin-field__label">{t("field.phone")}</span>
              <input
                type="tel"
                className="checkin-field__input"
                value={guest.phone ?? ""}
                onChange={(e) => updateGuest(idx, "phone", e.target.value)}
              />
            </label>

            <label className="checkin-field">
              <span className="checkin-field__label">{t("field.documentType")}</span>
              <select
                className="checkin-field__input"
                value={guest.document_type ?? ""}
                onChange={(e) =>
                  updateGuest(
                    idx,
                    "document_type",
                    e.target.value || null,
                  )
                }
              >
                <option value="">{t("field.selectDoc")}</option>
                <option value="ci">{t("field.docCi")}</option>
                <option value="pasaport">{t("field.docPassport")}</option>
                <option value="permis">{t("field.docPermit")}</option>
              </select>
            </label>

            <label className="checkin-field">
              <span className="checkin-field__label">{t("field.documentNumber")}</span>
              <input
                type="text"
                className="checkin-field__input"
                value={guest.document_number ?? ""}
                onChange={(e) =>
                  updateGuest(idx, "document_number", e.target.value)
                }
              />
            </label>

            <label className="checkin-field">
              <span className="checkin-field__label">{t("field.nationality")}</span>
              <input
                type="text"
                className="checkin-field__input"
                value={guest.nationality ?? ""}
                onChange={(e) =>
                  updateGuest(idx, "nationality", e.target.value)
                }
                placeholder="RO"
              />
            </label>

            <label className="checkin-field">
              <span className="checkin-field__label">{t("field.birthDate")}</span>
              <input
                type="date"
                className="checkin-field__input"
                value={guest.birth_date ?? ""}
                onChange={(e) =>
                  updateGuest(idx, "birth_date", e.target.value)
                }
              />
            </label>
          </div>
        </div>
      ))}
    </div>
  );
}

function StepValidation({
  validation,
  t,
}: {
  validation: ValidationResult | null;
  t: ReturnType<typeof useTranslations>;
}) {
  if (!validation) return null;

  const statusClass =
    validation.status === "ok"
      ? "checkin-validation--ok"
      : validation.status === "warning"
        ? "checkin-validation--warning"
        : "checkin-validation--blocked";

  return (
    <div className={`checkin-validation ${statusClass}`}>
      <div className="checkin-validation__status">
        {validation.status === "ok" && "✓"}
        {validation.status === "warning" && "⚠"}
        {validation.status === "blocked" && "✕"}
        <span>{t(`validation.${validation.status}`)}</span>
      </div>

      {validation.blockers.length > 0 && (
        <ul className="checkin-validation__list checkin-validation__list--blockers">
          {validation.blockers.map((b, i) => (
            <li key={i}>{b}</li>
          ))}
        </ul>
      )}

      {validation.flags.length > 0 && (
        <ul className="checkin-validation__list checkin-validation__list--flags">
          {validation.flags.map((f, i) => (
            <li key={i}>{t(`flag.${f}`)}</li>
          ))}
        </ul>
      )}

      {validation.status === "warning" && (
        <p className="checkin-validation__note">
          {t("validation.warningNote")}
        </p>
      )}
    </div>
  );
}

function StepPayment({
  booking,
  settings,
  paymentStatus,
  paymentAmount,
  depositAmount,
  onPaymentStatusChange,
  onPaymentAmountChange,
  onDepositAmountChange,
  t,
}: {
  booking: BookingForCheckin;
  settings: CheckinSettings;
  paymentStatus: PaymentStatus;
  paymentAmount: number;
  depositAmount: number;
  onPaymentStatusChange: (v: PaymentStatus) => void;
  onPaymentAmountChange: (v: number) => void;
  onDepositAmountChange: (v: number) => void;
  t: ReturnType<typeof useTranslations>;
}) {
  return (
    <div className="checkin-step-payment">
      <div className="checkin-payment__total">
        <span className="checkin-payment__total-label">{t("payment.totalDue")}</span>
        <span className="checkin-payment__total-value">
          {booking.total_price}
        </span>
      </div>

      <div className="checkin-payment__options">
        {(["paid", "partial", "unpaid"] as PaymentStatus[]).map((s) => (
          <label key={s} className="checkin-payment__option">
            <input
              type="radio"
              name="payment_status"
              value={s}
              checked={paymentStatus === s}
              onChange={() => {
                onPaymentStatusChange(s);
                if (s === "paid") onPaymentAmountChange(booking.total_price);
                if (s === "unpaid") onPaymentAmountChange(0);
              }}
            />
            <span>{t(`payment.${s}`)}</span>
          </label>
        ))}
      </div>

      {paymentStatus === "partial" && (
        <label className="checkin-field">
          <span className="checkin-field__label">{t("payment.amountPaid")}</span>
          <input
            type="number"
            className="checkin-field__input"
            min={0}
            max={booking.total_price}
            value={paymentAmount}
            onChange={(e) => onPaymentAmountChange(Number(e.target.value))}
          />
        </label>
      )}

      {settings.checkin_deposit && (
        <label className="checkin-field">
          <span className="checkin-field__label">{t("payment.deposit")}</span>
          <input
            type="number"
            className="checkin-field__input"
            min={0}
            value={depositAmount}
            onChange={(e) => onDepositAmountChange(Number(e.target.value))}
          />
        </label>
      )}
    </div>
  );
}

function StepFinish({
  booking,
  guests,
  paymentStatus,
  validation,
  keyHanded,
  notes,
  onKeyHandedChange,
  onNotesChange,
  t,
}: {
  booking: BookingForCheckin;
  guests: CheckinGuestInput[];
  paymentStatus: PaymentStatus;
  validation: ValidationResult | null;
  keyHanded: boolean;
  notes: string;
  onKeyHandedChange: (v: boolean) => void;
  onNotesChange: (v: string) => void;
  t: ReturnType<typeof useTranslations>;
}) {
  return (
    <div className="checkin-step-finish">
      {/* Summary */}
      <div className="checkin-summary">
        <div className="checkin-summary__row">
          <span className="checkin-summary__label">{t("field.guest")}</span>
          <span>{booking.guest_name}</span>
        </div>
        <div className="checkin-summary__row">
          <span className="checkin-summary__label">{t("field.dates")}</span>
          <span>
            {booking.check_in} → {booking.check_out}
          </span>
        </div>
        <div className="checkin-summary__row">
          <span className="checkin-summary__label">{t("payment.status")}</span>
          <span>{t(`payment.${paymentStatus}`)}</span>
        </div>
        <div className="checkin-summary__row">
          <span className="checkin-summary__label">{t("field.guestCount")}</span>
          <span>{guests.length}</span>
        </div>
        {validation && validation.flags.length > 0 && (
          <div className="checkin-summary__row checkin-summary__row--flags">
            <span className="checkin-summary__label">{t("flags")}</span>
            <span>
              {validation.flags.map((f) => t(`flag.${f}`)).join(", ")}
            </span>
          </div>
        )}
      </div>

      {/* Key handed */}
      <label className="checkin-checkbox">
        <input
          type="checkbox"
          checked={keyHanded}
          onChange={(e) => onKeyHandedChange(e.target.checked)}
        />
        <span>{t("keyHanded")}</span>
      </label>

      {/* Notes */}
      <label className="checkin-field">
        <span className="checkin-field__label">{t("field.notes")}</span>
        <textarea
          className="checkin-field__input checkin-field__input--textarea"
          rows={2}
          value={notes}
          onChange={(e) => onNotesChange(e.target.value)}
          placeholder={t("field.notesPlaceholder")}
        />
      </label>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { Link, useRouter } from "@/i18n/navigation";
import { useLocale, useTranslations } from "next-intl";
import { GanttCheckTimeDialog } from "@/components/admin/gantt/GanttCheckTimeDialog";
import { useAdminFx } from "@/components/admin/feedback/AdminToastProvider";
import { formatGuestPartyDetail } from "@/lib/guest-party";
import { formatStayPeriod } from "@/lib/ro-calendar";
import type { CheckInQuestItem } from "@/services/today-board";

type Props = {
  todayIso: string;
  checkInTime: string;
  pending: CheckInQuestItem[];
  completedCount: number;
};

export function CheckInMilestoneBoard({
  todayIso,
  checkInTime,
  pending,
  completedCount,
}: Props) {
  const t = useTranslations("admin.dashboard.checkInQuest");
  const locale = useLocale();
  const router = useRouter();
  const { showToast } = useAdminFx();
  const [dismissed, setDismissed] = useState<Set<string>>(new Set());
  const [dialog, setDialog] = useState<CheckInQuestItem | null>(null);

  const visible = useMemo(
    () => pending.filter((item) => !dismissed.has(item.bookingId)),
    [pending, dismissed]
  );

  const totalToday = completedCount + pending.length;
  const doneCount = completedCount + (pending.length - visible.length);
  const progressPct =
    totalToday > 0 ? Math.round((doneCount / totalToday) * 100) : 0;
  const allDone = totalToday > 0 && visible.length === 0;
  const noArrivalsToday = totalToday === 0;

  function handleSuccess(item: CheckInQuestItem) {
    setDismissed((prev) => new Set(prev).add(item.bookingId));
    setDialog(null);
    showToast({
      kind: "success",
      title: t("checkedInTitle"),
      message: item.guestLabel,
    });
    router.refresh();
  }

  return (
    <section
      className={[
        "checkin-quest",
        allDone && "checkin-quest--victory",
        noArrivalsToday && "checkin-quest--idle",
      ]
        .filter(Boolean)
        .join(" ")}
      aria-labelledby="checkin-quest-title"
    >
      <div className="checkin-quest__head">
        <div className="checkin-quest__head-text">
          <p className="checkin-quest__eyebrow">{t("eyebrow")}</p>
          <h2 id="checkin-quest-title" className="checkin-quest__title">
            {t("title")}
          </h2>
          <p className="checkin-quest__subtitle">
            {t("subtitle", { time: checkInTime })}
          </p>
        </div>

        {!noArrivalsToday && (
          <div className="checkin-quest__progress-wrap" aria-hidden={allDone}>
            <div
              className="checkin-quest__ring"
              style={{ "--quest-pct": `${progressPct}` } as React.CSSProperties}
            >
              <span className="checkin-quest__ring-value">{progressPct}%</span>
            </div>
            <p className="checkin-quest__progress-label">
              {t("progress", { done: doneCount, total: totalToday })}
            </p>
          </div>
        )}
      </div>

      {allDone && (
        <div className="checkin-quest__victory" role="status">
          <span className="checkin-quest__victory-icon" aria-hidden>
            ✓
          </span>
          <div>
            <p className="checkin-quest__victory-title">{t("allDoneTitle")}</p>
            <p className="checkin-quest__victory-msg">{t("allDoneMessage")}</p>
          </div>
        </div>
      )}

      {noArrivalsToday && (
        <p className="checkin-quest__idle">{t("noArrivalsToday")}</p>
      )}

      {visible.length > 0 && (
        <ul className="checkin-quest__track">
          {visible.map((item, index) => (
            <li key={item.bookingId} className="checkin-quest__step">
              <div className="checkin-quest__connector" aria-hidden />
              <article className="checkin-quest__card">
                <div className="checkin-quest__card-badge" aria-hidden>
                  {index + 1 + completedCount}
                </div>
                <div className="checkin-quest__card-body">
                  <p className="checkin-quest__guest">{item.guestLabel}</p>
                  <p className="checkin-quest__meta">
                    {item.roomNames.length > 0
                      ? item.roomNames.join(", ")
                      : t("noRoom")}
                    {" · "}
                    {formatGuestPartyDetail(item.numAdults, item.numChildren)}
                  </p>
                  <p className="checkin-quest__dates">
                    {formatStayPeriod(item.checkIn, item.checkOut, locale, true)}
                  </p>
                </div>
                <div className="checkin-quest__card-actions">
                  <button
                    type="button"
                    className="checkin-quest__cta"
                    onClick={() => setDialog(item)}
                  >
                    {t("checkInCta")}
                  </button>
                  <Link
                    href={`/admin/bookings/${item.bookingId}`}
                    className="checkin-quest__link"
                  >
                    {t("openBooking")}
                  </Link>
                </div>
              </article>
            </li>
          ))}
        </ul>
      )}

      {dialog && (
        <GanttCheckTimeDialog
          open
          mode="checkin"
          bookingId={dialog.bookingId}
          guestName={dialog.guestName}
          plannedCheckIn={dialog.checkIn}
          plannedCheckOut={dialog.checkOut}
          onClose={() => setDialog(null)}
          onSuccess={() => handleSuccess(dialog)}
        />
      )}
    </section>
  );
}

