"use client";

import { useEffect, useMemo, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import { AdminPortal } from "@/components/admin/overlay/AdminPortal";
import {
  useAdminPending,
  useRunAdminAction,
} from "@/components/admin/feedback/AdminPendingProvider";
import { useAdminFx } from "@/components/admin/feedback/AdminToastProvider";
import {
  editBookingCheckInAction,
  editBookingCheckOutAction,
  setBookingCheckInAction,
  setBookingCheckOutAction,
} from "@/app/[locale]/admin/(panel)/bookings/actions";
import {
  canOfferOperativeCheckIn,
  isOperativeCheckInTimestampValid,
  operativeCheckInDatetimeBounds,
} from "@/domain/booking/operative-checkin";
import { datetimeLocalNow } from "@/lib/operational-check";
import { formatStayPeriod } from "@/lib/ro-calendar";
import { todayIso } from "@/lib/stay-dates";

export type GanttCheckTimeDialogProps = {
  open: boolean;
  mode: "checkin" | "checkout";
  intent?: "set" | "edit";
  bookingId: string;
  guestName: string;
  plannedCheckIn: string;
  plannedCheckOut: string;
  today?: string;
  status?: string;
  actualCheckInAt?: string | null;
  actualCheckOutAt?: string | null;
  onClose: () => void;
  onSuccess?: () => void;
};

export function GanttCheckTimeDialog({
  open,
  mode,
  intent = "set",
  bookingId,
  guestName,
  plannedCheckIn,
  plannedCheckOut,
  today: todayProp,
  status = "confirmata",
  actualCheckInAt = null,
  actualCheckOutAt = null,
  onClose,
  onSuccess,
}: GanttCheckTimeDialogProps) {
  const tCommon = useTranslations("admin.common");
  const tGantt = useTranslations("admin.gantt");
  const tServer = useTranslations("admin.serverActions");
  const locale = useLocale();
  const { pending } = useAdminPending();
  const runAdminAction = useRunAdminAction();
  const { showToast } = useAdminFx();
  const [atLocal, setAtLocal] = useState(datetimeLocalNow);

  const effectiveToday = todayProp ?? todayIso();

  const checkInAllowed = useMemo(
    () =>
      mode !== "checkin" ||
      intent === "edit" ||
      canOfferOperativeCheckIn({
        status,
        plannedCheckIn,
        today: effectiveToday,
        actualCheckInAt,
        actualCheckOutAt,
      }),
    [
      mode,
      intent,
      status,
      plannedCheckIn,
      effectiveToday,
      actualCheckInAt,
      actualCheckOutAt,
    ]
  );

  const datetimeBounds = useMemo(
    () =>
      mode === "checkin" && intent === "set"
        ? operativeCheckInDatetimeBounds(plannedCheckIn)
        : null,
    [mode, intent, plannedCheckIn]
  );

  useEffect(() => {
    if (!open) return;
    if (mode === "checkin" && intent === "set" && datetimeBounds) {
      const now = datetimeLocalNow();
      const inBounds =
        now >= datetimeBounds.min && now <= datetimeBounds.max;
      setAtLocal(inBounds ? now : `${plannedCheckIn}T12:00`);
      return;
    }
    setAtLocal(datetimeLocalNow());
  }, [open, bookingId, mode, intent, plannedCheckIn, datetimeBounds]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  if (!open) return null;

  const title =
    mode === "checkin"
      ? tGantt("checkTime.confirmCheckIn")
      : tGantt("checkTime.confirmCheckOut");
  const cta =
    mode === "checkin"
      ? tGantt("checkTime.confirmCheckIn")
      : tGantt("checkTime.confirmCheckOut");

  function submit(at?: string) {
    if (
      mode === "checkin" &&
      intent === "set" &&
      !isOperativeCheckInTimestampValid(plannedCheckIn, at)
    ) {
      showToast({
        kind: "error",
        title: tCommon("error"),
        message: tServer("checkInOnlyOnArrivalDay"),
      });
      return;
    }

    void runAdminAction(async () => {
      const fd = new FormData();
      fd.set("id", bookingId);
      if (at) fd.set("at", at);

      const res =
        mode === "checkin"
          ? intent === "edit"
            ? await editBookingCheckInAction(fd)
            : await setBookingCheckInAction(fd)
          : intent === "edit"
            ? await editBookingCheckOutAction(fd)
            : await setBookingCheckOutAction(fd);

      if (!res.ok) {
        showToast({ kind: "error", title: tCommon("error"), message: res.error });
        return;
      }

      showToast({
        kind: "success",
        title:
          mode === "checkin"
            ? tGantt("checkTime.checkInRecorded")
            : tGantt("checkTime.checkOutRecorded"),
        message: guestName,
      });
      onClose();
      onSuccess?.();
    });
  }

  const submitDisabled = pending || (mode === "checkin" && intent === "set" && !checkInAllowed);

  return (
    <AdminPortal>
      <button
        type="button"
        className="fixed inset-0 z-[220] bg-black/40"
        aria-label={tCommon("close")}
        onClick={onClose}
      />
      <div
        className="fixed left-1/2 top-1/2 z-[221] w-[min(22rem,92vw)] -translate-x-1/2 -translate-y-1/2 rounded-xl border border-zinc-200 bg-white p-4 shadow-xl"
        role="dialog"
        aria-labelledby="gantt-check-time-title"
      >
        <h2 id="gantt-check-time-title" className="text-sm font-bold text-zinc-900">
          {title}
        </h2>
        <p className="mt-1 text-xs text-zinc-600">{guestName}</p>
        <p className="mt-0.5 text-[11px] text-zinc-500">
          {tGantt("checkTime.planned")}:{" "}
          {formatStayPeriod(plannedCheckIn, plannedCheckOut, locale, true)}
        </p>

        {mode === "checkin" && intent === "set" && !checkInAllowed && (
          <p className="mt-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-900">
            {tServer("checkInOnlyOnArrivalDay")}
          </p>
        )}

        <label className="mt-4 block text-xs font-semibold text-zinc-800">
          {tGantt("checkTime.dateTime")}
          <input
            type="datetime-local"
            value={atLocal}
            onChange={(e) => setAtLocal(e.target.value)}
            min={datetimeBounds?.min}
            max={datetimeBounds?.max}
            className="mt-1 w-full rounded-md border border-zinc-300 px-2 py-1.5 text-sm"
            disabled={pending || (mode === "checkin" && intent === "set" && !checkInAllowed)}
          />
        </label>

        <div className="mt-4 flex flex-wrap gap-2">
          <button
            type="button"
            className="rounded-md bg-zinc-900 px-3 py-1.5 text-xs font-semibold text-white disabled:opacity-50"
            disabled={submitDisabled}
            onClick={() => submit(atLocal)}
          >
            {pending ? tCommon("saving") : cta}
          </button>
          <button
            type="button"
            className="rounded-md border border-zinc-300 px-3 py-1.5 text-xs font-semibold text-zinc-800 disabled:opacity-50"
            disabled={submitDisabled}
            onClick={() => submit()}
          >
            {tCommon("now")}
          </button>
          <button
            type="button"
            className="rounded-md px-3 py-1.5 text-xs text-zinc-500"
            disabled={pending}
            onClick={onClose}
          >
            {tCommon("cancel")}
          </button>
        </div>
      </div>
    </AdminPortal>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import { useLocale, useTranslations } from "next-intl";
import { useAdminPendingOptional } from "@/components/admin/feedback/AdminPendingProvider";
import { useGanttContextMenu } from "@/components/admin/gantt/GanttContextMenuContext";
import type { GanttCreateDraft } from "@/components/admin/gantt/GanttCreateDialog";
import {
  LONG_PRESS_MS,
  LONG_PRESS_MOVE_PX,
} from "@/domain/gantt/context-menu";
import {
  clearGanttRoomDragSpan,
  findGanttRoomAtPoint,
  listGanttRoomIdsInDomOrder,
  setGanttRoomDragSpan,
} from "@/domain/gantt/room-at-point";
import type { PinnedSelection } from "@/domain/gantt/pinned-selection";
import {
  dayIndexFromPointerX,
  ghostBarPosition,
  intervalFromDayIndices,
} from "@/domain/gantt/drag-create";
import { findOccupancyConflicts } from "@/domain/occupancy/conflict";
import type { OccupancySegment } from "@/domain/occupancy/types";
import type { GanttViewRange } from "@/domain/gantt/view-range";
import {
  DEFAULT_CHECK_IN_TIME,
  DEFAULT_CHECK_OUT_TIME,
} from "@/lib/constants";
import { formatStayPeriod } from "@/lib/ro-calendar";

const BLOCK_INTERACTION_SELECTOR = "[data-gantt-block-interaction]";

type Props = {
  roomId: string;
  roomName: string;
  viewRange: GanttViewRange;
  occupancyByRoom: Map<string, OccupancySegment[]>;
  checkInTime?: string;
  checkOutTime?: string;
  touch: boolean;
  renderGrid: ReactNode;
  children: ReactNode;
  onCreateDraft: (draft: GanttCreateDraft) => void;
  pinnedSelection?: PinnedSelection | null;
  onCtrlDragEnd?: (roomIds: string[], checkIn: string, checkOut: string) => void;
};

type DragState = {
  startIdx: number;
  endIdx: number;
  hasConflict: boolean;
  roomCount: number;
  selectionMode: "range" | "ctrl";
};

function blocksDragCreate(target: EventTarget | null): boolean {
  return (
    target instanceof Element && !!target.closest(BLOCK_INTERACTION_SELECTOR)
  );
}

function nightCountFromIndices(startIdx: number, endIdx: number): number {
  return Math.max(1, endIdx - startIdx + 1);
}

function roomIdsBetween(
  orderedRoomIds: string[],
  startRoomId: string,
  endRoomId: string
): string[] {
  const startIndex = orderedRoomIds.indexOf(startRoomId);
  const endIndex = orderedRoomIds.indexOf(endRoomId);
  if (startIndex === -1 || endIndex === -1) return [startRoomId];

  const from = Math.min(startIndex, endIndex);
  const to = Math.max(startIndex, endIndex);
  return orderedRoomIds.slice(from, to + 1);
}

function appendUniqueRoomId(roomIds: string[], roomId: string | null): string[] {
  if (!roomId) return roomIds;
  return roomIds.includes(roomId) ? roomIds : [...roomIds, roomId];
}

export function GanttDragCreateLayer({
  roomId,
  roomName,
  viewRange,
  occupancyByRoom,
  checkInTime = DEFAULT_CHECK_IN_TIME,
  checkOutTime = DEFAULT_CHECK_OUT_TIME,
  touch,
  renderGrid,
  children,
  onCreateDraft,
  pinnedSelection,
  onCtrlDragEnd,
}: Props) {
  const tCommon = useTranslations("admin.common");
  const tGantt = useTranslations("admin.gantt");
  const locale = useLocale();
  const { openMenu } = useGanttContextMenu();
  const pendingCtx = useAdminPendingOptional();
  const rowRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{
    startIdx: number;
    endIdx: number;
    startRoomId: string;
    currentRoomId: string;
    selectedRoomIds: string[];
    orderedRoomIds: string[];
    selectionMode: "range" | "ctrl";
  } | null>(null);
  const longPressTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pressOriginRef = useRef<{ x: number; y: number } | null>(null);
  const armedStartIdxRef = useRef<number | null>(null);
  const armedSelectionModeRef = useRef<"range" | "ctrl">("range");
  const longPressOpenedRef = useRef(false);
  const [drag, setDrag] = useState<DragState | null>(null);

  const dayIsos = viewRange.days.map((d) => d.iso);
  const dayCount = dayIsos.length;

  const evalConflictForRooms = useCallback(
    (checkIn: string, checkOut: string, roomIds: string[]) => {
      for (const rid of roomIds) {
        const occ = occupancyByRoom.get(rid) ?? [];
        const conflicts = findOccupancyConflicts(
          [rid],
          checkIn,
          checkOut,
          occ,
          undefined,
          { checkIn: checkInTime, checkOut: checkOutTime }
        );
        if (conflicts.length > 0) return true;
      }
      return false;
    },
    [occupancyByRoom, checkInTime, checkOutTime]
  );

  const evalConflict = useCallback(
    (checkIn: string, checkOut: string) =>
      evalConflictForRooms(checkIn, checkOut, [roomId]),
    [roomId, evalConflictForRooms]
  );

  const clearLongPress = useCallback(() => {
    if (longPressTimerRef.current) {
      clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
  }, []);

  const openEmptyMenu = useCallback(
    (clientX: number, clientY: number, dayIdx: number) => {
      const interval = intervalFromDayIndices(dayIsos, dayIdx, dayIdx);
      if (!interval) return;
      openMenu({
        kind: "create",
        clientX,
        clientY,
        roomId,
        roomName,
        checkIn: interval.checkIn,
        checkOut: interval.checkOut,
        hasConflict: evalConflict(interval.checkIn, interval.checkOut),
      });
    },
    [dayIsos, roomId, roomName, evalConflict, openMenu]
  );

  const dayIdxAt = useCallback(
    (clientX: number) => {
      const row = rowRef.current;
      if (!row || dayCount === 0) return 0;
      const rect = row.getBoundingClientRect();
      return dayIndexFromPointerX(clientX, rect.left, rect.width, dayCount);
    },
    [dayCount]
  );

  const finishDrag = useCallback(
    (startIdx: number, endIdx: number, roomIds: string[]) => {
      const interval = intervalFromDayIndices(dayIsos, startIdx, endIdx);
      if (!interval) return;
      const uniqueRooms = [...new Set(roomIds.length ? roomIds : [roomId])];
      onCreateDraft({
        roomId,
        roomIds: uniqueRooms,
        roomName:
          uniqueRooms.length > 1
            ? `${uniqueRooms.length} ${tCommon("rooms")}`
            : roomName,
        checkIn: interval.checkIn,
        checkOut: interval.checkOut,
        hasConflict: evalConflictForRooms(
          interval.checkIn,
          interval.checkOut,
          uniqueRooms
        ),
      });
      clearGanttRoomDragSpan();
    },
    [dayIsos, roomId, roomName, evalConflictForRooms, onCreateDraft]
  );

  const updateDragAt = useCallback(
    (clientX: number, clientY: number) => {
      const row = rowRef.current;
      if (!row || !dragRef.current || dayCount === 0) return;
      const rect = row.getBoundingClientRect();
      let endIdx = dayIndexFromPointerX(
        clientX,
        rect.left,
        rect.width,
        dayCount
      );
      const startIdx = dragRef.current.startIdx;
      if (endIdx < startIdx) endIdx = startIdx;
      const hitRoom = findGanttRoomAtPoint(clientX, clientY);
      const currentRoomId = hitRoom ?? dragRef.current.currentRoomId;
      const roomIds =
        dragRef.current.selectionMode === "ctrl"
          ? appendUniqueRoomId(dragRef.current.selectedRoomIds, currentRoomId)
          : roomIdsBetween(
              dragRef.current.orderedRoomIds,
              dragRef.current.startRoomId,
              currentRoomId
            );
      const interval = intervalFromDayIndices(dayIsos, startIdx, endIdx);
      const hasConflict = interval
        ? evalConflictForRooms(interval.checkIn, interval.checkOut, roomIds)
        : false;
      const ghost = ghostBarPosition(startIdx, endIdx, dayCount);
      if (ghost) {
        setGanttRoomDragSpan(roomIds, {
          leftPct: ghost.leftPct,
          widthPct: ghost.widthPct,
          hasConflict,
        });
      } else {
        setGanttRoomDragSpan(roomIds);
      }
      dragRef.current = {
        ...dragRef.current,
        endIdx,
        currentRoomId,
        selectedRoomIds: roomIds,
      };
      setDrag({
        startIdx,
        endIdx,
        hasConflict,
        roomCount: roomIds.length,
        selectionMode: dragRef.current.selectionMode,
      });
    },
    [dayCount, dayIsos, evalConflictForRooms]
  );

  const beginDrag = useCallback(
    (
      startIdx: number,
      clientX: number,
      clientY: number,
      selectionMode: "range" | "ctrl"
    ) => {
      const ghost = ghostBarPosition(startIdx, startIdx, dayCount);
      const orderedRoomIds = listGanttRoomIdsInDomOrder();
      dragRef.current = {
        startIdx,
        endIdx: startIdx,
        startRoomId: roomId,
        currentRoomId: roomId,
        selectedRoomIds: [roomId],
        orderedRoomIds:
          orderedRoomIds.length > 0 ? orderedRoomIds : [roomId],
        selectionMode,
      };
      setDrag({
        startIdx,
        endIdx: startIdx,
        hasConflict: false,
        roomCount: 1,
        selectionMode,
      });
      if (ghost) {
        setGanttRoomDragSpan([roomId], {
          leftPct: ghost.leftPct,
          widthPct: ghost.widthPct,
          hasConflict: false,
        });
      } else {
        setGanttRoomDragSpan([roomId]);
      }
      updateDragAt(clientX, clientY);
    },
    [dayCount, roomId, updateDragAt]
  );

  const endDrag = useCallback(() => {
    if (longPressOpenedRef.current) {
      longPressOpenedRef.current = false;
      dragRef.current = null;
      setDrag(null);
      armedStartIdxRef.current = null;
      return;
    }
    if (!dragRef.current) return;
    const { startIdx, endIdx, selectedRoomIds, selectionMode } = dragRef.current;
    dragRef.current = null;
    setDrag(null);
    armedStartIdxRef.current = null;

    if (selectionMode === "ctrl" && onCtrlDragEnd) {
      const interval = pinnedSelection
        ? { checkIn: pinnedSelection.checkIn, checkOut: pinnedSelection.checkOut }
        : intervalFromDayIndices(dayIsos, startIdx, endIdx);
      if (interval) {
        onCtrlDragEnd(selectedRoomIds, interval.checkIn, interval.checkOut);
      }
      clearGanttRoomDragSpan();
      return;
    }
    finishDrag(startIdx, endIdx, selectedRoomIds);
  }, [finishDrag, onCtrlDragEnd, pinnedSelection, dayIsos]);

  useEffect(() => {
    if (!drag) return;

    const scrollEl = rowRef.current?.closest(".gantt-scroll");
    scrollEl?.classList.add("gantt-scroll--drag-lock");

    const onMove = (e: PointerEvent) => {
      if (!dragRef.current) return;
      e.preventDefault();
      updateDragAt(e.clientX, e.clientY);
    };

    const onUp = () => {
      endDrag();
      clearGanttRoomDragSpan();
    };

    window.addEventListener("pointermove", onMove, { passive: false });
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);

    return () => {
      scrollEl?.classList.remove("gantt-scroll--drag-lock");
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [drag, updateDragAt, endDrag]);

  const onPointerDown = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (pendingCtx?.pending) return;
      if (e.button !== 0) return;
      if (blocksDragCreate(e.target)) return;
      const row = rowRef.current;
      if (!row || dayCount === 0) return;

      longPressOpenedRef.current = false;
      pressOriginRef.current = { x: e.clientX, y: e.clientY };
      clearLongPress();
      const idx = dayIdxAt(e.clientX);
      armedStartIdxRef.current = idx;
      armedSelectionModeRef.current = e.ctrlKey || e.metaKey ? "ctrl" : "range";
      longPressTimerRef.current = setTimeout(() => {
        longPressOpenedRef.current = true;
        armedStartIdxRef.current = null;
        armedSelectionModeRef.current = "range";
        dragRef.current = null;
        setDrag(null);
        openEmptyMenu(e.clientX, e.clientY, idx);
      }, LONG_PRESS_MS);
      row.setPointerCapture(e.pointerId);
      e.preventDefault();
    },
    [dayCount, dayIdxAt, clearLongPress, openEmptyMenu, pendingCtx?.pending]
  );

  const onPointerUpRow = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      clearLongPress();
      pressOriginRef.current = null;
      armedStartIdxRef.current = null;
      armedSelectionModeRef.current = "range";

      try {
        rowRef.current?.releasePointerCapture(e.pointerId);
      } catch {
        /* ignore */
      }

      if (longPressOpenedRef.current) {
        longPressOpenedRef.current = false;
        dragRef.current = null;
        setDrag(null);
        clearGanttRoomDragSpan();
        return;
      }

      if (dragRef.current) {
        endDrag();
        clearGanttRoomDragSpan();
        return;
      }
    },
    [clearLongPress, endDrag]
  );

  const onPointerMoveRow = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      const origin = pressOriginRef.current;
      if (origin && !longPressOpenedRef.current) {
        const dx = e.clientX - origin.x;
        const dy = e.clientY - origin.y;
        if (Math.hypot(dx, dy) > LONG_PRESS_MOVE_PX) {
          clearLongPress();
          if (!dragRef.current) {
            beginDrag(
              armedStartIdxRef.current ?? dayIdxAt(origin.x),
              e.clientX,
              e.clientY,
              armedSelectionModeRef.current
            );
          }
        }
      }
    },
    [beginDrag, clearLongPress, dayIdxAt]
  );

  const onPointerCancelRow = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      onPointerUpRow(e);
    },
    [onPointerUpRow]
  );

  const ghost =
    drag && dayCount > 0
      ? ghostBarPosition(drag.startIdx, drag.endIdx, dayCount)
      : null;

  const dragInterval =
    drag && dayCount > 0
      ? intervalFromDayIndices(dayIsos, drag.startIdx, drag.endIdx)
      : null;

  const nights =
    drag != null ? nightCountFromIndices(drag.startIdx, drag.endIdx) : 0;

  const dragPeriod =
    dragInterval != null
      ? formatStayPeriod(dragInterval.checkIn, dragInterval.checkOut, locale, true)
      : "";

  return (
    <div
      ref={rowRef}
      data-gantt-room-drag-layer={roomId}
      className={[
          "gantt-drag-row relative w-full overflow-visible bg-white",
        touch && "gantt-drag-row--touch",
        drag && "gantt-drag-row--active",
      ]
        .filter(Boolean)
        .join(" ")}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMoveRow}
      onPointerUp={onPointerUpRow}
      onPointerCancel={onPointerCancelRow}
      aria-label={tGantt("dragCreate.aria", { roomName })}
    >
      <div className="pointer-events-none absolute inset-0">{renderGrid}</div>

      <div className="pointer-events-none absolute inset-0 z-[2]">
        <div className="relative h-full w-full">{children}</div>
      </div>

      {ghost && drag && (
        <div
          className={[
            "gantt-drag-preview pointer-events-none absolute z-[50] flex min-w-0 items-center overflow-hidden",
            drag.hasConflict
              ? "gantt-drag-preview--conflict"
              : "gantt-drag-preview--free",
          ].join(" ")}
          style={{
            left: `${ghost.leftPct}%`,
            width: `${ghost.widthPct}%`,
            minWidth: "2.75rem",
          }}
        >
          <span className="gantt-drag-preview__label truncate px-1.5">
            {drag.selectionMode === "ctrl"
              ? tGantt("dragCreate.ctrlRooms", { count: drag.roomCount })
              : drag.roomCount > 1
                ? tGantt("dragCreate.rooms", { count: drag.roomCount })
                : ""}
            {tGantt("quick.nightsLabel", { count: nights })}
            {ghost.widthPct > 8 ? ` · ${dragPeriod}` : ""}
          </span>
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import { useIsTouchDevice } from "@/hooks/useDeviceClass";
import { useAdminPending, useRunAdminAction } from "@/components/admin/feedback/AdminPendingProvider";
import { useRouter } from "@/i18n/navigation";
import {
  moveBookingRoomFromPivotAction,
  shiftBookingOnGanttAction,
} from "@/app/[locale]/admin/(panel)/calendar/actions";
import {
  clearGanttRoomDropTargets,
  findGanttRoomAtPoint,
  getGanttRoomDragLayer,
  setGanttRoomDropTarget,
} from "@/domain/gantt/room-at-point";
import { useAdminFx } from "@/components/admin/feedback/AdminToastProvider";
import { useGanttContextMenu } from "@/components/admin/gantt/GanttContextMenuContext";
import {
  LONG_PRESS_MS,
  LONG_PRESS_MOVE_PX,
} from "@/domain/gantt/context-menu";
import type { MoveRoomDraft } from "@/components/admin/gantt/MoveRoomDialog";
import type { OccupancyPhase } from "@/domain/occupancy/types";
import { GanttBookingBar } from "@/components/admin/GanttBookingBar";
import type { GanttBarPosition } from "@/domain/gantt/bar-position";
import type { StayTodayHighlight } from "@/domain/gantt/today-activity";
import { formatStayPeriod } from "@/lib/ro-calendar";
import { AdminAlertDialog } from "@/components/admin/overlay/AdminAlertDialog";
import {
  GanttStayPopover,
  type GanttStayPopoverData,
} from "./GanttStayPopover";
import { addDays, todayIso } from "@/lib/stay-dates";
import { dayIndexFromPointerX } from "@/domain/gantt/drag-create";

const DRAG_BLOCK_SELECTOR = [
  "a",
  "button",
  "input",
  "select",
  "textarea",
  "label",
  "summary",
  "details",
  "[role='button']",
  "[contenteditable='true']",
  "[data-gantt-no-drag]",
  "[data-admin-overlay]",
  ".admin-floating-panel",
].join(", ");

function blocksStayDragStart(target: EventTarget | null): boolean {
  return target instanceof Element && !!target.closest(DRAG_BLOCK_SELECTOR);
}

function shouldUseVerticalDrag(canVerticalMove: boolean, dx: number, dy: number): boolean {
  if (!canVerticalMove) return false;
  const absX = Math.abs(dx);
  const absY = Math.abs(dy);
  // Relaxed: 16px vertical threshold (half a row), and vertical must
  // simply exceed horizontal (not 1.35x). Makes room-to-room drag natural.
  return absY >= 16 && absY > absX;
}

type Props = {
  href: string;
  label: string;
  pos: GanttBarPosition;
  isCerere: boolean;
  guestTotal: number;
  bookingId: string;
  dayIsos: string[];
  bookingCheckIn: string;
  buildingColor?: string | null;
  todayHighlight?: StayTodayHighlight;
  initials?: string;
  popover: GanttStayPopoverData;
  actualCheckInAt?: string | null;
  actualCheckOutAt?: string | null;
  occupancyPhase?: OccupancyPhase;
  roomIds?: string[];
  guestId?: string | null;
  moveRoomDraft?: MoveRoomDraft | null;
  sourceRoomId?: string;
  canVerticalMove?: boolean;
  onMoveRoom?: () => void;
  today?: string;
};

export function GanttDraggableStay({
  href,
  label,
  pos,
  isCerere,
  guestTotal,
  bookingId,
  dayIsos,
  bookingCheckIn,
  buildingColor,
  todayHighlight,
  initials,
  popover,
  actualCheckInAt = null,
  actualCheckOutAt = null,
  occupancyPhase = "active",
  roomIds = [],
  guestId,
  moveRoomDraft,
  sourceRoomId = "",
  canVerticalMove = false,
  onMoveRoom,
  today,
}: Props) {
  const tGantt = useTranslations("admin.gantt");
  const locale = useLocale();
  const router = useRouter();
  const touch = useIsTouchDevice();
  const { openMenu } = useGanttContextMenu();
  const { notifyMoved } = useAdminFx();
  const { pending } = useAdminPending();
  const runAdminAction = useRunAdminAction();
  const [interaction, setInteraction] = useState<"idle" | "armed" | "dragging">("idle");
  const [snapped, setSnapped] = useState(false);
  const [hover, setHover] = useState(false);
  const [popoverHover, setPopoverHover] = useState(false);
  const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null);
  const [alertMsg, setAlertMsg] = useState<string | null>(null);
  const [dragDelta, setDragDelta] = useState(0);
  const [dragDeltaY, setDragDeltaY] = useState(0);
  const [verticalMode, setVerticalMode] = useState(false);
  const startX = useRef(0);
  const startY = useRef(0);
  const targetRoomRef = useRef<string | null>(null);
  const dragDeltaRef = useRef(0);
  const dragDeltaYRef = useRef(0);
  const lastPointerX = useRef(0);
  const lastPointerY = useRef(0);
  const hoverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const leaveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressOpened = useRef(false);
  const captureEl = useRef<HTMLDivElement | null>(null);
  const capturePointerId = useRef<number | null>(null);

  const dragging = interaction === "dragging";
  const visibleDayCount = dayIsos.length;

  const title = [
    popover.guestName,
    formatStayPeriod(popover.checkIn, popover.checkOut, locale),
    dragging
      ? verticalMode
        ? tGantt("drag.dragOtherRow")
        : tGantt("drag.leftRightDatesUpDownRoom")
      : tGantt("drag.defaultHint"),
  ].join(" · ");

  const openStayMenu = useCallback(
    (clientX: number, clientY: number) => {
      openMenu({
        kind: "stay",
        clientX,
        clientY,
        bookingId,
        guestId: guestId ?? null,
        guestName: popover.guestName,
        status: popover.status,
        occupancyPhase,
        today: today ?? todayIso(),
        roomIds,
        actualCheckInAt,
        actualCheckOutAt,
        plannedCheckIn: bookingCheckIn,
        plannedCheckOut: popover.checkOut,
        canMoveRoom: !!popover.canMoveRoom && !!moveRoomDraft,
        moveRoomDraft: moveRoomDraft ?? null,
        popover: {
          ...popover,
          onMoveRoom,
        },
      });
    },
    [
      openMenu,
      bookingId,
      bookingCheckIn,
      guestId,
      popover,
      occupancyPhase,
      today,
      roomIds,
      actualCheckInAt,
      actualCheckOutAt,
      moveRoomDraft,
      onMoveRoom,
    ]
  );

  const clearLongPress = useCallback(() => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  }, []);

  const onPointerDown = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (pending) return;
      if (e.button !== 0) return;
      if (blocksStayDragStart(e.target)) {
        e.stopPropagation();
        return;
      }
      e.stopPropagation();
      const el = e.currentTarget;
      startX.current = e.clientX;
      startY.current = e.clientY;
      lastPointerX.current = e.clientX;
      lastPointerY.current = e.clientY;
      targetRoomRef.current = null;
      longPressOpened.current = false;
      setVerticalMode(false);
      setDragDelta(0);
      setDragDeltaY(0);
      setInteraction("armed");
      captureEl.current = el;
      capturePointerId.current = e.pointerId;
      clearLongPress();
      longPressTimer.current = setTimeout(() => {
        longPressOpened.current = true;
        setInteraction("idle");
        openStayMenu(e.clientX, e.clientY);
      }, LONG_PRESS_MS);
      el.setPointerCapture(e.pointerId);
    },
    [clearLongPress, openStayMenu, pending]
  );

  useEffect(() => {
    if (interaction !== "armed" && interaction !== "dragging") return;

    const onMove = (e: PointerEvent) => {
      if (interaction === "armed") {
        const dx = e.clientX - startX.current;
        const dy = e.clientY - startY.current;
        if (Math.hypot(dx, dy) > LONG_PRESS_MOVE_PX && !longPressOpened.current) {
          clearLongPress();
          lastPointerX.current = e.clientX;
          lastPointerY.current = e.clientY;
          setDragDelta(dx);
          setDragDeltaY(dy);
          dragDeltaRef.current = dx;
          dragDeltaYRef.current = dy;
          const isVertical = shouldUseVerticalDrag(canVerticalMove, dx, dy);
          setVerticalMode(isVertical);
          if (isVertical) {
            const target = findGanttRoomAtPoint(e.clientX, e.clientY, sourceRoomId);
            targetRoomRef.current = target;
            setGanttRoomDropTarget(
              target && target !== sourceRoomId ? target : null
            );
          } else {
            targetRoomRef.current = null;
            setGanttRoomDropTarget(null);
          }
          setInteraction("dragging");
        }
        return;
      }

      const dx = e.clientX - startX.current;
      const dy = e.clientY - startY.current;
      lastPointerX.current = e.clientX;
      lastPointerY.current = e.clientY;
      setDragDelta(dx);
      setDragDeltaY(dy);
      dragDeltaRef.current = dx;
      dragDeltaYRef.current = dy;
      const isVertical = shouldUseVerticalDrag(canVerticalMove, dx, dy);
      setVerticalMode(isVertical);
      if (isVertical) {
        const target = findGanttRoomAtPoint(e.clientX, e.clientY, sourceRoomId);
        targetRoomRef.current = target;
        setGanttRoomDropTarget(
          target && target !== sourceRoomId ? target : null
        );
      } else {
        targetRoomRef.current = null;
        setGanttRoomDropTarget(null);
      }
    };

    const finish = (e?: PointerEvent) => {
      clearLongPress();
      const el = captureEl.current;
      const pid = capturePointerId.current;
      if (el && pid != null) {
        try {
          el.releasePointerCapture(pid);
        } catch {
          /* ignore */
        }
      }
      captureEl.current = null;
      capturePointerId.current = null;

      if (interaction === "armed" || longPressOpened.current) {
        setInteraction("idle");
        return;
      }

      setInteraction("idle");
      clearGanttRoomDropTargets();
      const dx = dragDeltaRef.current;
      const dy = dragDeltaYRef.current;
      const clientX = e?.clientX ?? lastPointerX.current;
      const clientY = e?.clientY ?? lastPointerY.current;
      const isVertical = shouldUseVerticalDrag(canVerticalMove, dx, dy);
      const targetRoom =
        targetRoomRef.current ?? findGanttRoomAtPoint(clientX, clientY, sourceRoomId);
      setDragDelta(0);
      setDragDeltaY(0);
      setVerticalMode(false);
      targetRoomRef.current = null;

      if (isVertical && targetRoom && targetRoom !== sourceRoomId) {
        void runAdminAction(async () => {
          const res = await moveBookingRoomFromPivotAction({
            bookingId,
            sourceRoomId,
            targetRoomId: targetRoom,
          });
          if (!res.ok) {
            setAlertMsg(res.error);
            return;
          }
          setSnapped(true);
          window.setTimeout(() => setSnapped(false), 360);
          notifyMoved(tGantt("moveRoom.moved"), popover.guestName);
        });
        // Refresh OUTSIDE the lock — doesn't block UI or further actions
        // Server already revalidated cache; this just fetches fresh data
        window.setTimeout(() => router.refresh(), 300);
        return;
      }

      if (visibleDayCount === 0) return;

      const targetLayer =
        getGanttRoomDragLayer(targetRoom ?? sourceRoomId) ??
        getGanttRoomDragLayer(sourceRoomId);
      if (!targetLayer) return;

      const gridRect = targetLayer.getBoundingClientRect();
      if (gridRect.width <= 0) return;

      const dayWidth = gridRect.width / visibleDayCount;
      if (dayWidth <= 0) return;

      const pointerDayIndex = dayIndexFromPointerX(
        clientX,
        gridRect.left,
        gridRect.width,
        visibleDayCount
      );
      const visualStartIndex = Math.max(
        0,
        Math.min(visibleDayCount - 1, Math.floor((pos.leftPct / 100) * visibleDayCount))
      );
      const dayDelta = pointerDayIndex - visualStartIndex;
      const targetCheckIn = addDays(bookingCheckIn, dayDelta);
      if (targetCheckIn === bookingCheckIn) return;

      void runAdminAction(async () => {
        const res = await shiftBookingOnGanttAction(bookingId, dayDelta);
        if (!res.ok) {
          setAlertMsg(res.error);
          return;
        }
        setSnapped(true);
        window.setTimeout(() => setSnapped(false), 360);
        notifyMoved();
      });
      // Refresh OUTSIDE the lock
      window.setTimeout(() => router.refresh(), 300);
    };

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", finish);
    window.addEventListener("pointercancel", finish);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", finish);
      window.removeEventListener("pointercancel", finish);
      clearGanttRoomDropTargets();
    };
  }, [
    interaction,
    clearLongPress,
    canVerticalMove,
    sourceRoomId,
    bookingId,
    bookingCheckIn,
    dayIsos,
    router,
    notifyMoved,
    popover.guestName,
    pos.leftPct,
    runAdminAction,
    visibleDayCount,
  ]);

  const showPopover =
    !touch && (hover || popoverHover) && interaction === "idle" && !pending;

  const clearLeaveTimer = () => {
    if (leaveTimer.current) {
      clearTimeout(leaveTimer.current);
      leaveTimer.current = null;
    }
  };

  const scheduleHidePopover = () => {
    clearLeaveTimer();
    leaveTimer.current = setTimeout(() => {
      setHover(false);
      setPopoverHover(false);
    }, 220);
  };

  const openBooking = useCallback(() => {
    router.push(`/admin/bookings/${bookingId}`);
  }, [router, bookingId]);

  return (
    <>
      <div
        data-gantt-block-interaction=""
        data-gantt-stay=""
        className={[
          "gantt-draggable-stay pointer-events-auto absolute z-[1] flex min-w-0 items-stretch",
          dragging && "cursor-grabbing",
          dragging && "gantt-draggable-stay--dragging",
          dragging && !verticalMode && "z-[20]",
          verticalMode && "gantt-draggable-stay--vertical",
          pending && "opacity-60",
        ]
          .filter(Boolean)
          .join(" ")}
        onDoubleClick={(e) => {
          e.preventDefault();
          openBooking();
        }}
        style={{
          left: `${pos.leftPct}%`,
          width: `${pos.widthPct}%`,
          maxWidth: `${100 - pos.leftPct}%`,
          transform: dragging
            ? `translate(${dragDelta}px, ${dragDeltaY}px)`
            : undefined,
        }}
        onPointerDown={onPointerDown}
        onContextMenu={(e) => {
          e.preventDefault();
          e.stopPropagation();
          openStayMenu(e.clientX, e.clientY);
        }}
        onMouseEnter={(e) => {
          clearLeaveTimer();
          const rect = e.currentTarget.getBoundingClientRect();
          setAnchorRect(rect);
          hoverTimer.current = setTimeout(() => setHover(true), 200);
        }}
        onMouseLeave={() => {
          if (hoverTimer.current) clearTimeout(hoverTimer.current);
          scheduleHidePopover();
        }}
      >
        <GanttBookingBar
          href={href}
          label={label}
          title={title}
          pos={pos}
          isCerere={isCerere}
          guestTotal={guestTotal}
          buildingColor={buildingColor}
          checkIn={popover.checkIn}
          checkOut={popover.checkOut}
          today={today}
          todayHighlight={todayHighlight}
          initials={initials}
          interactive
          extraClass={snapped ? "gantt-stay-chrome--snapped" : undefined}
          occupancyPhase={occupancyPhase}
        />
      </div>
      <GanttStayPopover
        data={{
          ...popover,
          onMoveRoom: onMoveRoom
            ? () => {
                popover.onMoveRoom?.();
                onMoveRoom();
              }
            : popover.onMoveRoom,
        }}
        anchorRect={anchorRect}
        visible={showPopover}
        onMouseEnter={() => {
          clearLeaveTimer();
          setPopoverHover(true);
        }}
        onMouseLeave={scheduleHidePopover}
        today={today}
      />
      <AdminAlertDialog
        open={!!alertMsg}
        message={alertMsg ?? ""}
        onClose={() => setAlertMsg(null)}
      />
    </>
  );
}

