              transform: `translate(calc(-50% + ${action.offsetX}px), calc(-50% + ${action.offsetY}px))`,
            }}
            className={[
              "absolute z-10 flex min-h-[5.3rem] w-[10.5rem] flex-col items-center justify-center rounded-[1.55rem] border px-4 text-center shadow-[0_18px_45px_-24px_rgba(15,23,42,0.5)] transition",
              action.tone,
              isDisabled
                ? "cursor-not-allowed opacity-45 shadow-none"
                : "hover:scale-[1.02] hover:shadow-[0_24px_55px_-24px_rgba(15,23,42,0.5)]",
            ].join(" ")}
          >
            <span className="text-[1.03rem] font-extrabold leading-none">
              {action.label}
            </span>
            <span className="mt-1 text-[11px] font-bold uppercase tracking-[0.08em] opacity-75">
              {action.hint}
            </span>
          </button>
        );
      })}
    </div>
  );
}

export function GanttQuickActionPanel({
  mode,
  rooms,
  bookings = [],
  draft = null,
  onClose,
  onModeChange,
  today: todayProp,
}: Props) {
  const tCommon = useTranslations("admin.common");
  const tGantt = useTranslations("admin.gantt");
  const locale = useLocale();
  const router = useRouter();
  const { showToast, notifyMoved } = useAdminFx();
  const { pending } = useAdminPending();
  const runAdminAction = useRunAdminAction();
  const effectiveToday = todayProp ?? todayIso();

  const confirmedBookings = useMemo(
    () =>
      bookings.filter(
        (booking) => booking.status === "confirmata" && booking.room_ids.length > 0
      ),
    [bookings]
  );

  const defaultRoomId = rooms[0]?.id ?? "";
  const defaultBooking = confirmedBookings[0] ?? null;
  const [roomId, setRoomId] = useState(draft?.roomId ?? defaultRoomId);
  const [checkIn, setCheckIn] = useState(draft?.checkIn ?? effectiveToday);
  const [checkOut, setCheckOut] = useState(
    draft?.checkOut ?? addDays(draft?.checkIn ?? effectiveToday, 1)
  );
  const [reason, setReason] = useState("");
  const [expiresHours, setExpiresHours] = useState("");
  const [blockPreset, setBlockPreset] =
    useState<BlockReasonPresetId>("maintenance");
  const [blockCustom, setBlockCustom] = useState("");
  const [guestLastName, setGuestLastName] = useState("");
  const [guestFirstName, setGuestFirstName] = useState("");
  const [guestEmail, setGuestEmail] = useState("");
  const [guestPhone, setGuestPhone] = useState("");
  const [moveBookingId, setMoveBookingId] = useState(defaultBooking?.id ?? "");
  const [moveSourceRoomId, setMoveSourceRoomId] = useState(
    defaultBooking?.room_ids[0] ?? ""
  );
  const [moveTargetRoomId, setMoveTargetRoomId] = useState("");
  const [movePreviewState, setMovePreviewState] = useState<{
    key: string;
    text: string;
  } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const activeRoomId = roomId;
  const activeCheckIn = checkIn;
  const activeCheckOut = checkOut;
  const activeRoom =
    rooms.find((room) => room.id === activeRoomId) ??
    (draft
      ? { id: draft.roomId, name: draft.roomName, building_name: "" }
      : null);
  const period =
    activeCheckIn && activeCheckOut && activeCheckIn < activeCheckOut
      ? formatStayPeriod(activeCheckIn, activeCheckOut, locale, true)
      : "";
  const multiRoomCount = draft?.roomIds?.length ?? 0;
  const hasMultiRoomDraft = multiRoomCount > 1;
  const intervalInvalid =
    !activeCheckIn || !activeCheckOut || activeCheckIn >= activeCheckOut;
  const activeRoomIds = draft?.roomIds?.length
    ? draft.roomIds
    : activeRoomId
      ? [activeRoomId]
      : [];
  const hasConflict =
    !intervalInvalid &&
    activeRoomIds.length > 0 &&
    bookings.some(
      (booking) =>
        booking.status !== "anulata" &&
        booking.room_ids.some((id) => activeRoomIds.includes(id)) &&
        booking.check_in < activeCheckOut &&
        booking.check_out > activeCheckIn
    );
  const allowBack = !!draft && !!onModeChange && mode !== "pick" && mode !== "move";

  const selectedBooking = useMemo(
    () => confirmedBookings.find((booking) => booking.id === moveBookingId) ?? null,
    [confirmedBookings, moveBookingId]
  );

  const moveTargetOptions = useMemo(() => {
    if (!selectedBooking) return rooms;
    return rooms.filter((room) => !selectedBooking.room_ids.includes(room.id));
  }, [rooms, selectedBooking]);

  const movePreviewKey =
    selectedBooking && moveSourceRoomId && moveTargetRoomId
      ? `${selectedBooking.id}:${moveSourceRoomId}:${moveTargetRoomId}`
      : "";
  const movePreview =
    movePreviewState?.key === movePreviewKey ? movePreviewState.text : null;

  useEffect(() => {
    if (!selectedBooking || !moveSourceRoomId || !moveTargetRoomId) return;

    let cancelled = false;
    void previewRoomMoveAction({
      bookingId: selectedBooking.id,
      sourceRoomId: moveSourceRoomId,
      targetRoomId: moveTargetRoomId,
    }).then((res) => {
      if (cancelled) return;
      if (!res.ok) {
        setError(res.error);
        return;
      }
      setError(null);
      const sourceRoomName =
        rooms.find((room) => room.id === moveSourceRoomId)?.name ?? tGantt("quick.sourceRoom");
      const targetRoomName =
        rooms.find((room) => room.id === moveTargetRoomId)?.name ?? tGantt("quick.targetRoom");
      setMovePreviewState({
        key: `${selectedBooking.id}:${moveSourceRoomId}:${moveTargetRoomId}`,
        text:
          res.preview.mode === "full"
            ? `${sourceRoomName} → ${targetRoomName}: ${formatStayPeriod(res.preview.targetSegment.start, res.preview.targetSegment.end, locale, true)} · ` +
              `Total: ${res.preview.oldTotal} → ${res.preview.newTotal} RON`
            : `${sourceRoomName}: ${formatStayPeriod(res.preview.sourceSegment?.start ?? "", res.preview.sourceSegment?.end ?? "", locale, true)} · ` +
              `→ ${targetRoomName}: ${formatStayPeriod(res.preview.targetSegment.start, res.preview.targetSegment.end, locale, true)} · ` +
              `Total: ${res.preview.oldTotal} → ${res.preview.newTotal} RON`,
      });
    });

    return () => {
      cancelled = true;
    };
  }, [selectedBooking, moveSourceRoomId, moveTargetRoomId, rooms]);

  if (!mode) return null;

  function handleBack() {
    setError(null);
    onModeChange?.("pick");
  }

  function updateCheckIn(nextCheckIn: string) {
    setError(null);
    setCheckIn(nextCheckIn);
    if (!activeCheckOut || nextCheckIn >= activeCheckOut) {
      setCheckOut(addDays(nextCheckIn, 1));
    }
  }

  function updateCheckOut(nextCheckOut: string) {
    setError(null);
    setCheckOut(nextCheckOut);
  }

  function shiftInterval(days: number) {
    setError(null);
    setCheckIn((current) => addDays(current, days));
    setCheckOut((current) => addDays(current, days));
  }

  function setIntervalDuration(nights: number) {
    setError(null);
    setCheckOut(addDays(activeCheckIn || effectiveToday, nights));
  }

  function moveIntervalToToday() {
    const duration =
      activeCheckIn && activeCheckOut && activeCheckIn < activeCheckOut
        ? nightsBetween(activeCheckIn, activeCheckOut)
        : 1;
    setError(null);
    setCheckIn(effectiveToday);
    setCheckOut(addDays(effectiveToday, Math.max(1, duration)));
  }

  function ensureCreatableInterval() {
    if (intervalInvalid) {
      setError(tGantt("quick.errors.checkoutAfterCheckin"));
      return false;
    }
    return true;
  }

  function submitHold() {
    if (!activeRoomId) {
      setError(tGantt("quick.errors.chooseRoom"));
      return;
    }
    if (!ensureCreatableInterval()) return;
    setError(null);
    void runAdminAction(async () => {
      const hours = expiresHours.trim() ? Number(expiresHours) : null;
      const res =
        draft?.roomIds && draft.roomIds.length > 1
          ? await createRoomHoldsFromGanttAction({
              roomIds: draft.roomIds,
              checkIn: activeCheckIn,
              checkOut: activeCheckOut,
              reason,
              expiresHours: hours,
            })
          : await createRoomHoldFromGanttAction({
              roomId: activeRoomId,
              checkIn: activeCheckIn,
              checkOut: activeCheckOut,
              reason,
              expiresHours: hours,
            });

      if (!res.ok) {
        setError(res.error);
        return;
      }

      if (res.undo) {
        showGanttCreateUndoToast(
          showToast,
          router,
          draft?.roomIds && draft.roomIds.length > 1
            ? tGantt("quick.holdCreatedMany", { count: draft.roomIds.length })
            : tGantt("quick.holdCreated"),
          period,
          res.undo,
          {
            actionLabel: tGantt("quick.undoAction"),
            undoneTitle: tGantt("quick.undoneTitle"),
            undoneMessage: tGantt("quick.undoneMessage"),
          }
        );
      } else {
        showToast({ kind: "success", title: tGantt("quick.holdCreated"), message: period });
      }
      onClose();
      router.refresh();
    });
  }

  function submitBlock() {
    if (!activeRoomId) {
      setError(tGantt("quick.errors.chooseRoom"));
      return;
    }
    if (!ensureCreatableInterval()) return;
    const resolvedReason = resolveBlockReason(blockPreset, blockCustom);
    if (!resolvedReason) {
      setError(tGantt("quick.errors.blockReasonRequired"));
      return;
    }
    setError(null);
    void runAdminAction(async () => {
      const res = await createRoomBlockFromGanttAction({
        roomId: activeRoomId,
        checkIn: activeCheckIn,
        checkOut: activeCheckOut,
        reason: resolvedReason,
      });
      if (!res.ok) {
        setError(res.error);
        return;
      }
      if (res.undo) {
        showGanttCreateUndoToast(
          showToast,
          router,
          tGantt("quick.blockCreated"),
          period,
          res.undo,
          {
            actionLabel: tGantt("quick.undoAction"),
            undoneTitle: tGantt("quick.undoneTitle"),
            undoneMessage: tGantt("quick.undoneMessage"),
          }
        );
      } else {
        showToast({ kind: "success", title: tGantt("quick.blockCreated"), message: period });
      }
      onClose();
      router.refresh();
    });
  }

  function submitGuestCreate(kind: "cerere" | "direct") {
    if (!activeRoomId) {
      setError(tGantt("quick.errors.chooseRoom"));
      return;
    }
    if (!ensureCreatableInterval()) return;
    if (!guestPhone.trim()) {
      setError(tGantt("quick.errors.phoneRequired"));
      return;
    }
    setError(null);
    void runAdminAction(async () => {
      const payload = {
        roomId: activeRoomId,
        checkIn: activeCheckIn,
        checkOut: activeCheckOut,
        guestLastName,
        guestFirstName,
        guestEmail,
        guestPhone,
      };
      const res =
        kind === "cerere"
          ? await createCerereFromGanttAction(payload)
          : await createDirectStayFromGanttAction(payload);
      if (!res.ok) {
        setError(res.error);
        return;
      }
      showToast({
        kind: "success",
        title: kind === "cerere" ? tGantt("quick.requestCreated") : tGantt("quick.directCreated"),
        message:
          kind === "cerere"
            ? tGantt("quick.requestAppears")
            : tGantt("quick.bookingAppears"),
      });
      onClose();
      router.refresh();
    });
  }

  function submitMove() {
    if (!selectedBooking || !moveSourceRoomId || !moveTargetRoomId) {
      setError(tGantt("quick.errors.chooseBookingAndTarget"));
      return;
    }
    setError(null);
    void runAdminAction(async () => {
      const res = await moveBookingRoomFromPivotAction({
        bookingId: selectedBooking.id,
        sourceRoomId: moveSourceRoomId,
        targetRoomId: moveTargetRoomId,
      });
      if (!res.ok) {
        setError(res.error);
        return;
      }
      notifyMoved(tGantt("moveRoom.moved"), selectedBooking.guest_name);
      onClose();
      router.refresh();
    });
  }

  const titleMap: Record<GanttQuickPanelMode, string> = {
    pick: tGantt("quick.title.pick"),
    hold: tGantt("quick.title.hold"),
    block: tGantt("quick.title.block"),
    cerere: tGantt("quick.title.request"),
    direct: tGantt("quick.title.direct"),
    move: tGantt("quick.title.move"),
  };
  const intervalTitle = draft
    ? hasMultiRoomDraft
      ? tGantt("quick.multiRoomSelection")
      : tGantt("quick.selectedInterval")
    : tGantt("quick.bookingInterval");
  const intervalSubtitle = draft ? (
    <>
      <strong className="font-semibold text-zinc-900">
        {hasMultiRoomDraft
          ? `${multiRoomCount} camere selectate`
          : activeRoom?.name ?? draft.roomName}
      </strong>
      {!hasMultiRoomDraft && activeRoom?.building_name ? (
        <span className="text-zinc-500"> · {activeRoom.building_name}</span>
      ) : null}
    </>
  ) : (
    <>
        <strong className="font-semibold text-zinc-900">{activeRoom?.name ?? tGantt("quick.chooseRoom")}</strong>
      {activeRoom?.building_name ? (
        <span className="text-zinc-500"> · {activeRoom.building_name}</span>
      ) : null}
    </>
  );

  return (
    <AdminFloatingPanel
      open
      onClose={onClose}
      title={titleMap[mode]}
      variant="modal"
      width={640}
    >
      <div className="gantt-toolbar-occ-form space-y-4 p-1">
        {mode !== "move" ? (
          <>
            {!draft ? (
              <label className={labelClass}>
                Cameră
                <select
                  className={inputClass}
                  value={roomId}
                  onChange={(e) => {
                    setError(null);
                    setRoomId(e.target.value);
                  }}
                >
                  {rooms.map((room) => (
                    <option key={room.id} value={room.id}>
                      {room.name} · {room.building_name}
                    </option>
                  ))}
                </select>
              </label>
            ) : null}

            <IntervalPlanner
              title={intervalTitle}
              subtitle={intervalSubtitle}
              checkIn={activeCheckIn}
              checkOut={activeCheckOut}
              onCheckInChange={updateCheckIn}
              onCheckOutChange={updateCheckOut}
              onShift={shiftInterval}
              onSetDuration={setIntervalDuration}
              onToday={moveIntervalToToday}
              invalidInterval={intervalInvalid}
              hasConflict={hasConflict}
              invalidMessage={tGantt("quick.chooseCheckoutAfterCheckin")}
              nightLabel={(count) => tGantt("quick.nightsLabel", { count })}
              locale={locale}
            />

            {hasConflict ? (
              <SummaryCard
                title={tGantt("quick.conflict")}
                tone="warn"
                body={tGantt("quick.conflictBody")}
              />
            ) : null}

            {hasMultiRoomDraft ? (
              <SummaryCard
                title={tGantt("quick.note")}
                tone="info"
                body={tGantt("quick.multiRoomOnlyHold")}
              />
            ) : null}
          </>
        ) : null}

        {mode === "pick" ? (
          <ActionRadial
            disabled={{
              hold: hasConflict || intervalInvalid,
              block: hasConflict || hasMultiRoomDraft || intervalInvalid,
              cerere: hasConflict || hasMultiRoomDraft || intervalInvalid,
              direct: hasConflict || hasMultiRoomDraft || intervalInvalid,
            }}
            onSelect={(nextMode) => onModeChange?.(nextMode)}
            tGantt={tGantt}
          />
        ) : null}

        {mode === "hold" ? (
          <>
            <div className="grid gap-3 sm:grid-cols-2">
              <label className={labelClass}>
                Motiv
                <input
                  className={inputClass}
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  placeholder={tGantt("quick.holdReasonPlaceholder")}
                />
              </label>
              <label className={labelClass}>
                Expiră după
                <input
                  type="number"
                  min={1}
                  className={inputClass}
                  value={expiresHours}
                  onChange={(e) => setExpiresHours(e.target.value)}
                  placeholder={tGantt("quick.hoursOptionalPlaceholder")}
                />
              </label>
            </div>
            <div className="flex gap-2">
              {allowBack ? (
                <button
                  type="button"
                  className="admin-floating-panel__btn flex-1"
                  onClick={handleBack}
                >
                  Înapoi la radial
                </button>
              ) : null}
              <button
                type="button"
                className="admin-floating-panel__btn admin-floating-panel__btn--primary flex-1"
                disabled={pending || !activeRoomId || hasConflict || intervalInvalid}
                onClick={submitHold}
              >
                Creează hold
              </button>
            </div>
          </>
        ) : null}

        {mode === "block" ? (
          <>
            <label className={labelClass}>
              Motiv blocare
              <select
                className={inputClass}
                value={blockPreset}
                onChange={(e) =>
                  setBlockPreset(e.target.value as BlockReasonPresetId)
                }
              >
                {BLOCK_REASON_PRESETS.map((preset) => (
                  <option key={preset.id} value={preset.id}>
                    {preset.label}
                  </option>
                ))}
              </select>
            </label>
            {blockPreset === "other" || blockCustom ? (
              <label className={labelClass}>
                Detalii
                <input
                  className={inputClass}
                  value={blockCustom}
                  onChange={(e) => setBlockCustom(e.target.value)}
                  placeholder={tGantt("quick.shortDescription")}
                />
              </label>
            ) : null}
            <div className="flex gap-2">
              {allowBack ? (
                <button
                  type="button"
                  className="admin-floating-panel__btn flex-1"
                  onClick={handleBack}
                >
                  Înapoi la radial
                </button>
              ) : null}
              <button
                type="button"
                className="admin-floating-panel__btn admin-floating-panel__btn--primary flex-1"
                disabled={
                  pending ||
                  !activeRoomId ||
                  hasConflict ||
                  hasMultiRoomDraft ||
                  intervalInvalid
                }
                onClick={submitBlock}
              >
                Creează blocarea
              </button>
            </div>
          </>
        ) : null}

        {mode === "cerere" || mode === "direct" ? (
          <>
            <div className="grid gap-3 sm:grid-cols-2">
              <label className={labelClass}>
                Nume
                <input
                  className={inputClass}
                  value={guestLastName}
                  onChange={(e) => setGuestLastName(e.target.value)}
                />
              </label>
              <label className={labelClass}>
                Prenume
                <input
                  className={inputClass}
                  value={guestFirstName}
                  onChange={(e) => setGuestFirstName(e.target.value)}
                />
              </label>
            </div>
            <label className={labelClass}>
              Email
              <input
                type="email"
                className={inputClass}
                value={guestEmail}
                onChange={(e) => setGuestEmail(e.target.value)}
              />
            </label>
            <label className={labelClass}>
              Telefon *
              <input
                className={inputClass}
                type="tel"
                required
                value={guestPhone}
                onChange={(e) => setGuestPhone(e.target.value)}
              />
            </label>
            <div className="flex gap-2">
              {allowBack ? (
                <button
                  type="button"
                  className="admin-floating-panel__btn flex-1"
                  onClick={handleBack}
                >
                  Înapoi la radial
                </button>
              ) : null}
              <button
                type="button"
                className="admin-floating-panel__btn admin-floating-panel__btn--primary flex-1"
                disabled={
                  pending ||
                  !activeRoomId ||
                  hasConflict ||
                  hasMultiRoomDraft ||
                  intervalInvalid
                }
                onClick={() => submitGuestCreate(mode)}
              >
                {mode === "cerere" ? tGantt("quick.createRequest") : tGantt("quick.confirmStay")}
              </button>
            </div>
          </>
        ) : null}

        {mode === "move" ? (
          <>
            <label className={labelClass}>
              Rezervare confirmată
              <select
                className={inputClass}
                value={moveBookingId}
                onChange={(e) => {
                  const nextBookingId = e.target.value;
                  const nextBooking =
                    confirmedBookings.find((booking) => booking.id === nextBookingId) ??
                    null;
                  setError(null);
                  setMoveBookingId(nextBookingId);
                  setMoveSourceRoomId(nextBooking?.room_ids[0] ?? "");
                  setMoveTargetRoomId("");
                }}
              >
                <option value="">{tCommon("selectPlaceholder")}</option>
                {confirmedBookings.map((booking) => (
                  <option key={booking.id} value={booking.id}>
                    {booking.guest_name} · {booking.room_names.join(", ")}
                  </option>
                ))}
              </select>
            </label>

            {confirmedBookings.length === 0 ? (
              <SummaryCard
                title={tGantt("quick.moveUnavailable")}
                body={tGantt("quick.moveUnavailableBody")}
              />
            ) : null}

            {selectedBooking ? (
              <>
                <SummaryCard
                  title={tGantt("quick.selectedBooking")}
                  body={
                    <>
                      <strong className="font-semibold text-zinc-900">
                        {selectedBooking.guest_name}
                      </strong>
                      <div className="mt-1">
                        {formatStayPeriod(
                          selectedBooking.check_in,
                          selectedBooking.check_out,
                          true
                        )}
                      </div>
                    </>
                  }
                />
                <div className="grid gap-3 sm:grid-cols-2">
                  <label className={labelClass}>
                    Din camera
                    <select
                      className={inputClass}
                      value={moveSourceRoomId}
                      onChange={(e) => {
                        setError(null);
                        setMoveSourceRoomId(e.target.value);
                      }}
                    >
                      {selectedBooking.room_ids.map((id, index) => (
                        <option key={id} value={id}>
                          {selectedBooking.room_names[index] ?? id}
                        </option>
                      ))}
                    </select>
                  </label>
                  <label className={labelClass}>
                    În camera
                    <select
                      className={inputClass}
                      value={moveTargetRoomId}
                      onChange={(e) => {
                        setError(null);
                        setMoveTargetRoomId(e.target.value);
                      }}
                    >
                      <option value="">{tCommon("selectPlaceholder")}</option>
                      {moveTargetOptions.map((option) => (
                        <option key={option.id} value={option.id}>
                          {option.name} · {option.building_name}
                        </option>
                      ))}
                    </select>
                  </label>
                </div>
                {movePreview ? (
                  <SummaryCard title="Preview mutare" tone="info" body={movePreview} />
                ) : null}
                <button
                  type="button"
                  className="admin-floating-panel__btn admin-floating-panel__btn--primary w-full"
                  disabled={pending || !moveTargetRoomId}
                  onClick={submitMove}
                >
                  Confirmă mutarea
                </button>
              </>
            ) : null}
          </>
        ) : null}

        {error ? (
          <p
            className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700"
            role="alert"
          >
            {error}
          </p>
        ) : null}

        <button
          type="button"
          className="admin-floating-panel__btn w-full"
          onClick={onClose}
        >
          Anulează
        </button>
      </div>
    </AdminFloatingPanel>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "@/i18n/navigation";
import { useLocale, useTranslations } from "next-intl";
import {
  useAdminPending,
  useRunAdminAction,
} from "@/components/admin/feedback/AdminPendingProvider";
import {
  moveBookingRoomFromPivotAction,
  previewRoomMoveAction,
} from "@/app/[locale]/admin/(panel)/calendar/actions";
import { useAdminFx } from "@/components/admin/feedback/AdminToastProvider";
import { AdminFloatingPanel } from "@/components/admin/overlay/AdminFloatingPanel";
import { formatStayPeriod } from "@/lib/ro-calendar";

type RoomOption = { id: string; name: string; building_name: string };

export type MoveRoomDraft = {
  bookingId: string;
  guestName: string;
  sourceRoomId: string;
  sourceRoomName: string;
  roomIds: string[];
};

type Props = {
  draft: MoveRoomDraft | null;
  rooms: RoomOption[];
  onClose: () => void;
};

export function MoveRoomDialog({ draft, rooms, onClose }: Props) {
  const tCommon = useTranslations("admin.common");
  const tGantt = useTranslations("admin.gantt");
  const locale = useLocale();
  const router = useRouter();
  const { notifyMoved } = useAdminFx();
  const { pending } = useAdminPending();
  const runAdminAction = useRunAdminAction();
  const [targetRoomId, setTargetRoomId] = useState("");
  const [previewState, setPreviewState] = useState<{
    roomId: string;
    text: string | null;
    error: string | null;
  }>({
    roomId: "",
    text: null,
    error: null,
  });
  const [submitError, setSubmitError] = useState<string | null>(null);

  useEffect(() => {
    if (!draft || !targetRoomId || targetRoomId === draft.sourceRoomId) {
      return;
    }
    let cancelled = false;
    void previewRoomMoveAction({
      bookingId: draft.bookingId,
      sourceRoomId: draft.sourceRoomId,
      targetRoomId,
    }).then((res) => {
      if (cancelled) return;
      if (!res.ok) {
        setPreviewState({
          roomId: targetRoomId,
          text: null,
          error: res.error,
        });
        return;
      }
      const p = res.preview;
      setPreviewState({
        roomId: targetRoomId,
        error: null,
        text:
          p.mode === "full"
            ? `${draft.sourceRoomName} → ${rooms.find((r) => r.id === targetRoomId)?.name ?? tCommon("room")} · ` +
              `${formatStayPeriod(p.targetSegment.start, p.targetSegment.end, locale, true)} · ` +
              `${tCommon("total")}: ${p.oldTotal} → ${p.newTotal} RON`
            : `${draft.sourceRoomName}: ${formatStayPeriod(p.sourceSegment?.start ?? "", p.sourceSegment?.end ?? "", locale, true)} · ` +
              `→ ${rooms.find((r) => r.id === targetRoomId)?.name ?? tCommon("room")}: ${formatStayPeriod(p.targetSegment.start, p.targetSegment.end, locale, true)} · ` +
              `${tCommon("total")}: ${p.oldTotal} → ${p.newTotal} RON`,
      });
    });
    return () => {
      cancelled = true;
    };
  }, [draft, targetRoomId, rooms]);

  if (!draft) return null;

  const targets = rooms.filter(
    (r) => r.id !== draft.sourceRoomId && !draft.roomIds.includes(r.id)
  );
  const previewText =
    previewState.roomId === targetRoomId ? previewState.text : null;
  const error =
    submitError ?? (previewState.roomId === targetRoomId ? previewState.error : null);

  function submit() {
    if (!draft) return;
    const current = draft;
    if (!targetRoomId) {
      setSubmitError(tGantt("moveRoom.chooseTarget"));
      return;
    }
    setSubmitError(null);
    void runAdminAction(async () => {
      const res = await moveBookingRoomFromPivotAction({
        bookingId: current.bookingId,
        sourceRoomId: current.sourceRoomId,
        targetRoomId,
      });
      if (!res.ok) {
        setSubmitError(res.error);
        return;
      }
      notifyMoved(tGantt("moveRoom.moved"), tGantt("moveRoom.updated", { guestName: current.guestName }));
      onClose();
      router.refresh();
    });
  }

  return (
    <AdminFloatingPanel
      open
      onClose={onClose}
      title={tGantt("moveRoom.title")}
      variant="modal"
      width={440}
    >
      <div className="gantt-move-room space-y-3">
        <p className="text-sm text-zinc-600">
          <strong>{draft.guestName}</strong>
          <br />
          {tGantt.rich("moveRoom.introHtml", { room: () => <strong>{draft.sourceRoomName}</strong> })}
        </p>

        <label className="block text-xs font-semibold text-zinc-600">
          {tGantt("moveRoom.targetRoom")}
          <select
            className="mt-1 w-full rounded border border-zinc-300 px-2 py-1.5 text-sm"
            value={targetRoomId}
            onChange={(e) => {
              setTargetRoomId(e.target.value);
              setSubmitError(null);
            }}
          >
            <option value="">{tCommon("selectPlaceholder")}</option>
            {targets.map((r) => (
              <option key={r.id} value={r.id}>
                {r.name} · {r.building_name}
              </option>
            ))}
          </select>
        </label>

        {previewText ? (
          <p className="rounded-md border border-sky-200 bg-sky-50 px-3 py-2 text-xs text-sky-900">
            {previewText}
          </p>
        ) : null}

        {error ? (
          <p className="text-sm text-red-600" role="alert">
            {error}
          </p>
        ) : null}

        <button
          type="button"
          className="admin-floating-panel__btn admin-floating-panel__btn--primary w-full"
          disabled={pending || !targetRoomId}
          onClick={submit}
        >
          {tGantt("moveRoom.confirm")}
        </button>
        <button type="button" className="admin-floating-panel__btn w-full" onClick={onClose}>
          {tCommon("cancel")}
        </button>
      </div>
    </AdminFloatingPanel>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import type { GuestRow, GuestNationalIdType } from "@/domain/guest/types";
import {
  validateNationalId,
  cleanNationalId,
  NATIONAL_ID_LENGTH,
  NATIONAL_ID_COUNTRY,
  NATIONAL_ID_TYPES,
} from "@/domain/guest/national-id";
import type { NationalIdType } from "@/domain/guest/national-id";
import { updateGuestIdentityAction } from "@/app/[locale]/admin/(panel)/guests/actions";
import { isValidGuestPhone } from "@/domain/guest/normalize";
import {
  useAdminPending,
  useRunAdminAction,
} from "@/components/admin/feedback/AdminPendingProvider";
import { AdminAlertDialog } from "@/components/admin/overlay/AdminAlertDialog";

type DocType = "ci" | "passport" | "foreign_id" | "other" | "";

const ROMANIAN_COUNTIES = [
  "Alba", "Arad", "Argeș", "Bacău", "Bihor", "Bistrița-Năsăud", "Botoșani",
  "Brăila", "Brașov", "București", "Buzău", "Călărași", "Caraș-Severin",
  "Cluj", "Constanța", "Covasna", "Dâmbovița", "Dolj", "Galați", "Giurgiu",
  "Gorj", "Harghita", "Hunedoara", "Ialomița", "Iași", "Ilfov", "Maramureș",
  "Mehedinți", "Mureș", "Neamț", "Olt", "Prahova", "Sălaj", "Satu Mare",
  "Sibiu", "Suceava", "Teleorman", "Timiș", "Tulcea", "Vâlcea", "Vaslui",
  "Vrancea",
];

/** Mapping from country to default national ID type */
const COUNTRY_TO_ID_TYPE: Record<string, NationalIdType> = {
  "România": "cnp",
  "Romania": "cnp",
  "RO": "cnp",
  "Moldova": "idnp",
  "Republica Moldova": "idnp",
  "MD": "idnp",
  "Bulgaria": "egn",
  "BG": "egn",
  "Grecia": "amka",
  "Greece": "amka",
  "GR": "amka",
  "Ungaria": "amka",
  "Hungary": "szemelyi_szam",
  "HU": "szemelyi_szam",
};

function inferNationalIdType(country: string, nationality: string): NationalIdType {
  return COUNTRY_TO_ID_TYPE[country] ?? COUNTRY_TO_ID_TYPE[nationality] ?? "cnp";
}

function NationalIdTypePicker({
  value,
  onChange,
  disabled,
  labelForType,
}: {
  value: NationalIdType;
  onChange: (type: NationalIdType) => void;
  disabled?: boolean;
  labelForType: (type: NationalIdType) => string;
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onPointerDown(e: MouseEvent) {
      if (!rootRef.current?.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("mousedown", onPointerDown);
    return () => document.removeEventListener("mousedown", onPointerDown);
  }, [open]);

  return (
    <div ref={rootRef} className="guest-id-type-picker">
      <button
        type="button"
        className="guest-id-type-picker__trigger guest-identity-form__select"
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-label={labelForType(value)}
        title={labelForType(value)}
        disabled={disabled}
        onClick={() => setOpen((prev) => !prev)}
      >
        <span className="guest-id-type-picker__code">{NATIONAL_ID_COUNTRY[value]}</span>
        <span className="guest-id-type-picker__chevron" aria-hidden>
          ▾
        </span>
      </button>
      {open && (
        <ul className="guest-id-type-picker__menu" role="listbox" aria-label={labelForType(value)}>
          {NATIONAL_ID_TYPES.map((type) => (
            <li key={type} role="none">
              <button
                type="button"
                role="option"
                aria-selected={value === type}
                className={[
                  "guest-id-type-picker__option",
                  value === type && "guest-id-type-picker__option--active",
                ]
                  .filter(Boolean)
                  .join(" ")}
                onClick={() => {
                  onChange(type);
                  setOpen(false);
                }}
              >
                {labelForType(type)}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export function GuestIdentityForm({ guest }: { guest: GuestRow }) {
  const t = useTranslations("admin.guests.identity");
  const tCommon = useTranslations("admin.common");
  const tRoot = useTranslations("common");
  const tErrors = useTranslations("errors");
  const runAdminAction = useRunAdminAction();
  const { pending } = useAdminPending();

  const [docType, setDocType] = useState<DocType>(guest.doc_type ?? "");
  const [docSeries, setDocSeries] = useState(guest.doc_series ?? "");
  const [docNumber, setDocNumber] = useState(guest.doc_number ?? "");
  const [docIssuedBy, setDocIssuedBy] = useState(guest.doc_issued_by ?? "");
  const [docIssueDate, setDocIssueDate] = useState(guest.doc_issue_date ?? "");
  const [docExpiryDate, setDocExpiryDate] = useState(guest.doc_expiry_date ?? "");

  // National ID
  const [nationalIdType, setNationalIdType] = useState<NationalIdType>(
    (guest.national_id_type as NationalIdType) ?? "cnp"
  );
  const [nationalId, setNationalId] = useState(guest.national_id ?? guest.cnp ?? "");

  const [birthDate, setBirthDate] = useState(guest.birth_date ?? "");
  const [birthPlace, setBirthPlace] = useState(guest.birth_place ?? "");
  const [nationality, setNationality] = useState(guest.nationality ?? "România");
  const [address, setAddress] = useState(guest.address ?? "");
  const [city, setCity] = useState(guest.city ?? "");
  const [county, setCounty] = useState(guest.county ?? "");
  const [country, setCountry] = useState(guest.country ?? "România");
  const [sex, setSex] = useState<"M" | "F" | "">(guest.sex ?? "");
  const [phone, setPhone] = useState(guest.phone ?? "");

  const [idError, setIdError] = useState<string | null>(null);
  const [idAutoFilled, setIdAutoFilled] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const expectedLength = NATIONAL_ID_LENGTH[nationalIdType];

  const handleNationalIdChange = useCallback(
    (raw: string) => {
      setNationalId(raw);
      setIdError(null);
      setIdAutoFilled(false);

      const cleaned = cleanNationalId(raw);
      if (cleaned.length === expectedLength) {
        const result = validateNationalId(nationalIdType, cleaned);
        if (result.valid && result.data) {
          if (result.data.birthDate) setBirthDate(result.data.birthDate);
          if (result.data.sex) setSex(result.data.sex);
          setIdAutoFilled(true);
        } else {
          setIdError(t("nationalIdInvalid", { type: nationalIdType.toUpperCase() }));
        }
      }
    },
    [nationalIdType, expectedLength, t]
  );

  const handleNationalIdTypeChange = useCallback(
    (newType: NationalIdType) => {
      setNationalIdType(newType);
      setIdError(null);
      setIdAutoFilled(false);
      // Reset auto-filled values when switching type
      if (idAutoFilled) {
        setBirthDate("");
        setSex("");
      }
      // Auto-set country based on ID type
      const idCountry = NATIONAL_ID_COUNTRY[newType];
      const countryNames: Record<string, string> = {
        RO: "România", MD: "Republica Moldova", BG: "Bulgaria", GR: "Grecia", HU: "Ungaria",
      };
      if (idCountry && countryNames[idCountry]) {
        setCountry(countryNames[idCountry]);
        setNationality(countryNames[idCountry]);
      }
    },
    [idAutoFilled]
  );

  async function handleSubmit() {
    setError(null);
    setSuccess(false);

    if (!isValidGuestPhone(phone)) {
      setError(tErrors("phoneRequired"));
      return;
    }

    // Validate national ID if provided
    if (nationalId.trim()) {
      const cleaned = cleanNationalId(nationalId);
      const result = validateNationalId(nationalIdType, cleaned);
      if (!result.valid) {
        setError(t("nationalIdInvalid", { type: nationalIdType.toUpperCase() }));
        return;
      }
    }

    const formData = new FormData();
    formData.set("guest_id", guest.id);
    formData.set("phone", phone.trim());
    formData.set("doc_type", docType);
    formData.set("doc_series", docSeries);
    formData.set("doc_number", docNumber);
    formData.set("doc_issued_by", docIssuedBy);
    formData.set("doc_issue_date", docIssueDate);
    formData.set("doc_expiry_date", docExpiryDate);
    formData.set("national_id_type", nationalIdType);
    formData.set("national_id", cleanNationalId(nationalId));
    formData.set("birth_date", birthDate);
    formData.set("birth_place", birthPlace);
    formData.set("nationality", nationality);
    formData.set("address", address);
    formData.set("city", city);
    formData.set("county", county);
    formData.set("country", country);
    formData.set("sex", sex);

    try {
      await runAdminAction(() => updateGuestIdentityAction(formData));
      setSuccess(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : t("saveFailed"));
    }
  }

  const showDocFields = docType !== "";
  const showCiFields = docType === "ci";
  const idTypeLabel = t(`nationalIdTypes.${nationalIdType}`);

  return (
    <>
      <div className="guest-identity-form">
        <div className="guest-identity-form__status">
          <IdentityStatusPill status={guest.identity_status} t={t} />
        </div>

        {/* Document type */}
        <div className="guest-identity-form__section">
          <h4 className="guest-identity-form__section-title">{t("documentSection")}</h4>
          <div className="guest-identity-form__row">
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{t("docType")}</span>
              <select
                value={docType}
                onChange={(e) => setDocType(e.target.value as DocType)}
                className="guest-identity-form__select"
              >
                <option value="">{t("selectDocType")}</option>
                <option value="ci">{t("docTypes.ci")}</option>
                <option value="passport">{t("docTypes.passport")}</option>
                <option value="foreign_id">{t("docTypes.foreign_id")}</option>
                <option value="other">{t("docTypes.other")}</option>
              </select>
            </label>
          </div>

          {showDocFields && (
            <div className="guest-identity-form__row guest-identity-form__row--multi">
              {showCiFields && (
                <label className="guest-identity-form__field guest-identity-form__field--small">
                  <span className="guest-identity-form__label">{t("docSeries")}</span>
                  <input
                    type="text"
                    value={docSeries}
                    onChange={(e) => setDocSeries(e.target.value.toUpperCase())}
                    placeholder="XX"
                    maxLength={4}
                    className="guest-identity-form__input"
                  />
                </label>
              )}
              <label className="guest-identity-form__field">
                <span className="guest-identity-form__label">{t("docNumber")}</span>
                <input
                  type="text"
                  value={docNumber}
                  onChange={(e) => setDocNumber(e.target.value)}
                  placeholder={showCiFields ? "123456" : t("docNumberPlaceholder")}
                  className="guest-identity-form__input"
                />
              </label>
              <label className="guest-identity-form__field">
                <span className="guest-identity-form__label">{t("docIssuedBy")}</span>
                <input
                  type="text"
                  value={docIssuedBy}
                  onChange={(e) => setDocIssuedBy(e.target.value)}
                  placeholder={t("docIssuedByPlaceholder")}
                  className="guest-identity-form__input"
                />
              </label>
            </div>
          )}

          {showDocFields && (
            <div className="guest-identity-form__row guest-identity-form__row--multi">
              <label className="guest-identity-form__field">
                <span className="guest-identity-form__label">{t("docIssueDate")}</span>
                <input
                  type="date"
                  value={docIssueDate}
                  onChange={(e) => setDocIssueDate(e.target.value)}
                  className="guest-identity-form__input"
                />
              </label>
              <label className="guest-identity-form__field">
                <span className="guest-identity-form__label">{t("docExpiryDate")}</span>
                <input
                  type="date"
                  value={docExpiryDate}
                  onChange={(e) => setDocExpiryDate(e.target.value)}
                  className="guest-identity-form__input"
                />
              </label>
            </div>
          )}
        </div>

        {/* National ID — multi-country */}
        <div className="guest-identity-form__section">
          <h4 className="guest-identity-form__section-title">{t("personalSection")}</h4>

          <div className="guest-identity-form__row">
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{tRoot("phone")} *</span>
              <input
                type="tel"
                required
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder="07xx xxx xxx"
                className="guest-identity-form__input"
              />
            </label>
          </div>

          <div className="guest-identity-form__row guest-identity-form__row--multi">
            <label className="guest-identity-form__field guest-identity-form__field--small">
              <span className="guest-identity-form__label">{t("nationalIdType")}</span>
              <NationalIdTypePicker
                value={nationalIdType}
                onChange={handleNationalIdTypeChange}
                disabled={pending}
                labelForType={(type) => t(`nationalIdTypes.${type}`)}
              />
            </label>
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">
                {idTypeLabel}
                {idAutoFilled && (
                  <span className="guest-identity-form__auto-tag">{t("autoFilled")}</span>
                )}
              </span>
              <input
                type="text"
                value={nationalId}
                onChange={(e) => handleNationalIdChange(e.target.value)}
                placeholder={t("nationalIdPlaceholder", { digits: expectedLength })}
                maxLength={expectedLength + 2}
                inputMode="numeric"
                className={[
                  "guest-identity-form__input",
                  idError && "guest-identity-form__input--error",
                ].filter(Boolean).join(" ")}
              />
              {idError && (
                <span className="guest-identity-form__error">{idError}</span>
              )}
              <span className="guest-identity-form__hint">
                {t("nationalIdHint", { type: idTypeLabel, digits: expectedLength })}
              </span>
            </label>
          </div>

          <div className="guest-identity-form__row guest-identity-form__row--multi">
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">
                {t("sex")}
                {idAutoFilled && sex && (
                  <span className="guest-identity-form__auto-tag">{t("fromId")}</span>
                )}
              </span>
              <select
                value={sex}
                onChange={(e) => setSex(e.target.value as "M" | "F" | "")}
                disabled={idAutoFilled}
                className="guest-identity-form__select"
              >
                <option value="">{t("selectSex")}</option>
                <option value="M">{t("sexM")}</option>
                <option value="F">{t("sexF")}</option>
              </select>
            </label>
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">
                {t("birthDate")}
                {idAutoFilled && birthDate && (
                  <span className="guest-identity-form__auto-tag">{t("fromId")}</span>
                )}
              </span>
              <input
                type="date"
                value={birthDate}
                onChange={(e) => setBirthDate(e.target.value)}
                disabled={idAutoFilled}
                className="guest-identity-form__input"
              />
            </label>
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{t("birthPlace")}</span>
              <input
                type="text"
                value={birthPlace}
                onChange={(e) => setBirthPlace(e.target.value)}
                placeholder={t("birthPlacePlaceholder")}
                className="guest-identity-form__input"
              />
            </label>
          </div>

          <div className="guest-identity-form__row guest-identity-form__row--multi">
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{t("nationality")}</span>
              <input
                type="text"
                value={nationality}
                onChange={(e) => setNationality(e.target.value)}
                placeholder="România"
                className="guest-identity-form__input"
              />
            </label>
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{t("country")}</span>
              <input
                type="text"
                value={country}
                onChange={(e) => setCountry(e.target.value)}
                placeholder="România"
                className="guest-identity-form__input"
              />
            </label>
          </div>
        </div>

        {/* Address */}
        <div className="guest-identity-form__section">
          <h4 className="guest-identity-form__section-title">{t("addressSection")}</h4>
          <div className="guest-identity-form__row">
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{t("address")}</span>
              <input
                type="text"
                value={address}
                onChange={(e) => setAddress(e.target.value)}
                placeholder={t("addressPlaceholder")}
                className="guest-identity-form__input"
              />
            </label>
          </div>
          <div className="guest-identity-form__row guest-identity-form__row--multi">
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{t("city")}</span>
              <input
                type="text"
                value={city}
                onChange={(e) => setCity(e.target.value)}
                placeholder={t("cityPlaceholder")}
                className="guest-identity-form__input"
              />
            </label>
            <label className="guest-identity-form__field">
              <span className="guest-identity-form__label">{t("county")}</span>
              <select
                value={county}
                onChange={(e) => setCounty(e.target.value)}
                className="guest-identity-form__select"
              >
                <option value="">{t("selectCounty")}</option>
                {ROMANIAN_COUNTIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </label>
          </div>
        </div>

        {/* Actions */}
        <div className="guest-identity-form__actions">
          {success && (
            <span className="guest-identity-form__success">{t("savedOk")}</span>
          )}
          <button
            type="button"
            onClick={() => void handleSubmit()}
            disabled={pending || !!idError}
            className="guest-identity-form__submit"
          >
            {pending ? tCommon("saving") : t("save")}
          </button>
        </div>
      </div>

      <AdminAlertDialog
        open={error != null}
        title={t("errorTitle")}
        message={error ?? ""}
        onClose={() => setError(null)}
      />
    </>
  );
}

function IdentityStatusPill({
  status,
  t,
  compact = false,
}: {
  status: string;
  t: (key: string) => string;
  compact?: boolean;
}) {
  const cls = [
    "guest-identity-status",
    compact && "guest-identity-status--compact",
    status === "complete" && "guest-identity-status--complete",
    status === "partial" && "guest-identity-status--partial",
    status === "draft" && "guest-identity-status--draft",
  ]
    .filter(Boolean)
    .join(" ");

  const icon = status === "complete" ? "✓" : status === "partial" ? "○" : "−";
  const label = t(`status.${status}`);

  return (
    <span className={cls}>
      <span className="guest-identity-status__icon">{icon}</span>
      {label}
    </span>
  );
}

/** Exported for reuse in cards / badges */
export function GuestIdentityStatusPill({
  status,
  compact = false,
}: {
  status: string;
  compact?: boolean;
}) {
  const t = useTranslations("admin.guests.identity");
  return <IdentityStatusPill status={status} t={t} compact={compact} />;
}

